// كتاب الطهارة — القسم الثالث: من باب النهي عن التخلي في الطرق والظلال (ص134–...)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب النهي عن التخلي في الطرق والظلال (ص134–135)`,
    items: [
      { q: `معنى «اتقوا اللعانين» والنهي عن التخلي في طريق الناس وظلهم`, p: `135`,
        n: `قال الإمام أبو سليمان الخطابي: المراد باللاعنين الأمرين الجالبين للعن الحاملين الناس عليه والداعيين إليه، وذلك أن من فعلهما شتم ولعن، يعني عادة الناس لعنه، فلما صارا سببًا لذلك أضيف اللعن إليهما. قال: وقد يكون اللاعن بمعنى الملعون، والملاعن مواضع اللعن. قلت: فعلى هذا يكون التقدير: اتقوا الأمرين الملعون فاعلهما، وهذا على رواية أبي داود. وأما رواية مسلم فمعناها — والله أعلم — اتقوا فعل اللعانين أي: صاحبي اللعن، وهما اللذان يلعنهما الناس في العادة. قال الخطابي وغيره من العلماء: المراد بالظل هنا مستظل الناس الذي اتخذوه مقيلًا ومناخًا ينزلونه ويقعدون فيه، وليس كل ظل يحرم القعود تحته، فقد قعد النبي ﷺ تحت حايش النخل لحاجته وله ظل بلا شك. وأما قوله ﷺ «الذي يتخلى في طريق الناس» فمعناه يتغوط في موضع يمر به الناس، وما نهى عنه في الظل والطريق لما فيه من إيذاء المسلمين بتنجيس من يمر به ونتنه واستقذاره.`,
        o: NO_O,
        s: `فهما الأمران الجالبان للعن، و«اللعانين» صيغة مبالغة.` },
    ],
  },
  {
    title: `باب الاستنجاء بالماء من التبرز (ص136–138)`,
    items: [
      { q: `فوائد حديث أنس: الاستتار والتباعد لقضاء الحاجة، واستخدام الفاضل بعض أصحابه، والتبرك بخدمة الصالحين`, p: `137`,
        n: `ففيها: استحباب التباعد لقضاء الحاجة عن الناس، والاستتار عن أعين الناظرين. وفيها: جواز استخدام الرجل الفاضل بعض أصحابه في حاجته. وفيها: خدمة الصالحين وأهل الفضل والتبرك بذلك.`,
        o: NO_O,
        s: `(يتبرز لحاجته) فكلمة التبرز أصبحت في الاستعمال العرفي [نفس قضاء الحاجة]، وأخذه للعصى (العنزة) دليل على استحباب السترة. وأنس ﵁ كان خادم النبي ﷺ وليس عبدًا عنده. والتبرك هنا: أي طلب الخير من ذلك، وليس التبرك الاصطلاحي وهو طلب البركة من الملامسة والملابسة، ولكن طلب الخير الكثير بفعل الصلاح ويرجى كذلك من مصاحبة أهل الصلاح، فصحبة الصالحين فيها بركة. أما التبرك بالآثار كمسح الصالحين وأخذ عرقهم فالصحيح أن هذا خاص بالأنبياء على خلاف بين أهل العلم في ذلك، والراجح ما ذكرنا لترك الصحابة فعل ذلك مع غير النبي ﷺ وهو كالإجماع منهم، فلم يكونوا يتبركون مثلًا بوضوء أبي بكر ﵁ ولا بنخامة عمر ﵁ ولا بشعر عثمان ﵁ ولا بثياب علي ﵁ مثلًا.` },
      { q: `الاستنجاء بالماء والحجر: أيهما أفضل؟ والجمع بينهما، وهل يطهر الحجر المحل؟`, p: `137–138`,
        n: `وفيها: جواز الاستنجاء بالماء واستحبابه ورجحانه على الاقتصار على الحجر، وقد اختلف الناس في هذه المسألة: فالذي عليه الجماهير من السلف والخلف وأجمع عليه أهل الفتوى من أئمة الأمصار أن الأفضل أن يجمع بين الماء والحجر فيستعمل الحجر أولًا لتخف النجاسة وتقل مباشرتها بيده ثم يستعمل الماء، فإن أراد الاقتصار على أحدهما جاز الاقتصار على أيهما شاء سواء وجد الآخر أو لم يجده، فيجوز الاقتصار على الحجر مع وجود الماء ويجوز عكسه، فإن اقتصر على أحدهما فالماء أفضل من الحجر لأن الماء يطهر المحل طهارة حقيقية، وأما الحجر فلا يطهره، وإنما يخفف النجاسة ويبيح الصلاة مع النجاسة المعفو عنها. وبعض السلف ذهبوا إلى أن الأفضل هو الحجر، وربما أوهم كلام بعضهم أن الماء لا يجزي. وقال ابن حبيب المالكي: لا يجزي الحجر إلا لمن عدم الماء. وهذا خلاف ما عليه العلماء من السلف والخلف وخلاف ظواهر السنن المتظاهرة.`,
        o: `بعض السلف: الأفضل الحجر (وأوهم بعضهم أن الماء لا يجزي). وابن حبيب المالكي: لا يجزي الحجر إلا لمن عدم الماء.`,
        s: `الصحيح أن الحجر يطهر فهي طهارة حكمًا، ووجود النجاسة المعفو عنها كعدم وجودها، والدليل حديث: (إنهما لا يطهران) دليل أن غيرهما يطهر.` },
      { q: `الوضوء من الأواني دون المشارع (الترع) والبرك`, p: `138`,
        n: `وقد استدل بعض العلماء بهذه الأحاديث على أن المستحب أن يتوضأ من الأواني دون المشارع والبرك ونحوها، إذ لم ينقل ذلك عن النبي ﷺ، وهذا الذي قاله غير مقبول ولم يوافق عليه أحد فيما نعلم. قال القاضي عياض: هذا الذي قاله هذا القائل لا أصل له، ولم ينقل أن النبي ﷺ وجدها فعدل عنها إلى الأواني.`,
        o: `بعض العلماء: المستحب الوضوء من الأواني دون المشارع والبرك.`,
        s: `(المشارع أي الترع.) ويؤيده قوله ﷺ لما سئل: [أفنتوضأ من ماء البحر؟ فقال رسول الله ﷺ: «هو الطهور ماؤه الحل ميتته»] (ت 69، س 59، د 83، جه 388، صحيح الجامع 7048) فهو دليل على مشروعية ذلك. فإنه ﷺ كان يستعمل الأواني لأنها كانت هي المتيسرة.` },
      { q: `هل يعفى عن يسير أي نجاسة أم أن هذا مختص بالدم فقط؟ (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `على الدم وما ورد فيه الدليل من بول الصبي الذي لم يطعم الطعام، فهذا يعفى عن يسير النجاسة.` },
      { q: `هل القيح والصديد نجسان؟ (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `لم يذكر الله في الكتاب قيحًا ولا صديدًا، وإنما ذكر الدم، وذكر النبي ﷺ البول والغائط، والصحيح أن القيح والصديد إذا لم يشتملا على دم فليسوا بنجاسات، والأفضل تجنبها.` },
      { q: `هل الشك في النية بعد الفراغ من العبادة يؤثر في هذه العبادة؟ (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `هذا يكون من باب الوسوسة، فلا يؤثر فيها.` },
      { q: `إذا تعدت النجاسة موضع الحاجة: هل يجوز استخدام الحجر في إزالة عين النجاسة باستخدامه؟ (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `الجمهور يرون أن ذلك لا يزول إلا بالمائعات بالماء خصوصًا.` },
      { q: `رجل يصلي سنة المغرب فأتم به آخر مصليًا المغرب، فصلى الإمام ركعة ثالثة متعمدًا وقال إنه غيّر نيته من سنة المغرب إلى صلاة المغرب (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `الصلاة باطلة؛ لأنه لا بد أن يبدأ من أول تكبيرة الإحرام ناويًا المغرب الفرض، وبالتالي فصلاة الإمام باطلة وصلاة المأموم صحيحة.` },
      { q: `رجل باع محصول القمح قبل إخراج الزكاة، وأخرجها نقودًا (فتوى)`, p: `138`,
        n: NO_N, o: NO_O,
        s: `لا يجوز ذلك، يجب أن يخرجها قمحًا.` },
    ],
  },
  {
    title: `باب المسح على الخفين (ص139–150)`,
    items: [
      { q: `جواز المسح على الخفين في الحضر والسفر ولو لغير حاجة`, p: `141`,
        n: `أجمع من يعتد به في الإجماع على جواز المسح على الخفين في السفر والحضر، سواء كان لحاجة أو لغيرها، حتى يجوز للمرأة الملازمة بيتها والزمن الذي لا يمشي، وإنما أنكرته الشيعة والخوارج ولا يعتد بخلافهم، وقد روي عن مالك — رحمه الله تعالى — روايات فيه، والمشهور من مذهبه كمذهب الجماهير. وقد روى المسح على الخفين خلائق لا يحصون من الصحابة، قال الحسن البصري — رحمه الله تعالى —: حدثني سبعون من أصحاب رسول الله ﷺ أن رسول الله ﷺ كان يمسح على الخفين.`,
        o: `الشيعة والخوارج: أنكروه.`,
        s: `أي لا يلزم أن يكون ذلك لحاجة كبرد أو مرض أو سفر أو مشقة، بل يمكن أن يكون مع سهولة الأمر تمامًا (من غير حاجة) أي من غير مصلحة إلا التيسير على نفس المتوضئ.` },
      { q: `أيهما أفضل: المسح على الخفين أم غسل الرجلين؟`, p: `141`,
        n: `واختلف العلماء في أن المسح على الخفين أفضل أم غسل الرجلين؟ فذهب أصحابنا إلى أن الغسل أفضل لكونه الأصل، وذهب إليه جماعات من الصحابة منهم: عمر بن الخطاب، وابنه عبد الله، وأبو أيوب الأنصاري ﵃. وذهب جماعات من التابعين إلى أن المسح أفضل، وذهب إليه الشعبي والحكم وحماد. وعن أحمد روايتان: أصحهما: المسح أفضل، والثانية: هما سواء، واختاره ابن المنذر.`,
        o: `الشافعية وجماعة من الصحابة: الغسل أفضل. والشعبي والحكم وحماد وأحمد في رواية: المسح أفضل. وابن المنذر: هما سواء.`,
        s: `(وحجة من قال المسح أفضل: أن المسح أيسر والأيسر أفضل، ولأنه يتضمن الرد على أهل البدع وإظهار شعائر الدين، ولهذا يكون أفضل.) وقد رجح ابن القيم رحمه الله أن النبي ﷺ كان لا يتكلف نزع الخف ليغسل رجليه ولا يلبس الخفين ليمسح عليهما بل حسبما تيسر، والقول بأنهما سواء أو يختلف باختلاف الأحوال: فإن كانت رجله في الخف فالمستحب مسحها ولا يتكلف نزع الخف ليغسل رجليه، وإن كانت رجله من غير خف فالغسل أفضل ولا يتكلف لبس الخف من أجل المسح بل يفعل ما اتفق وما كان عليه حاله.` },
      { q: `حديث جرير وآية المائدة: هل نُسخ المسح بآية الوضوء؟ (وقراءة الجر «وأرجلِكم»)`, p: `142`,
        n: `قوله (كان يعجبهم هذا الحديث لأن إسلام جرير كان بعد نزول المائدة) معناه أن الله تعالى قال في سورة المائدة: ﴿فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ﴾ فلو كان إسلام جرير متقدمًا على نزول المائدة لاحتمل كون حديثه في مسح الخف منسوخًا بآية المائدة، فلما كان إسلامه متأخرًا علمنا أن حديثه يعمل به، وهو مبين أن المراد بآية المائدة غير صاحب الخف، فتكون السنة مخصصة للآية.`,
        o: NO_O,
        s: `والقرآن قد دل على المسح من قراءة آية المائدة (وامسحوا برؤوسكم وأرجلِكم إلى الكعبين) على أحد الوجهين في التفسير على هذه القراءة أنه المسح على الرجلين إن كان فيهما الخفان، فهو دليل قوي ظاهر مع الأحاديث الصحيحة المصرحة بجواز المسح. (لأن الآية في وجوب غسل الرجلين، أي ليس في رجله خف ومنطبقة عليه شروط المسح.) وكما ذكرنا الوجه الثاني وهو أن القراءة الأخرى دلت على مشروعية المسح.` },
      { q: `البول قائمًا: حكمه وسبب بول النبي ﷺ قائمًا`, p: `142–144`,
        n: `وأما سبب بوله ﷺ قائمًا فذكر العلماء فيه أوجهًا: أحدها: وهو مروي عن الشافعي أن العرب كانت تستشفي لوجع الصلب بالبول قائمًا، قال: فنرى أنه كان به ﷺ وجع الصلب إذ ذاك. والثاني: أن سببه ما روي في رواية ضعيفة رواها البيهقي وغيره: أنه ﷺ بال قائمًا لعلة بمأبضه (وهو باطن الركبة). والثالث: أنه لم يجد مكانًا للقعود فاضطر إلى القيام لكون الطرف الذي من السباطة كان عاليًا مرتفعًا. وذكر الإمام أبو عبد الله المازري والقاضي عياض وجهًا رابعًا: أنه بال قائمًا لكونها حالة يؤمن فيها خروج الحدث من السبيل الآخر في الغالب، بخلاف حالة القعود، ولذلك قال عمر: البول قائمًا أحصن للدبر. ويجوز وجه خامس: أنه ﷺ فعله للجواز في هذه المرة، وكانت عادته المستمرة يبول قاعدًا، يدل عليه حديث عائشة ﵂ قالت: (من حدثكم أن النبي ﷺ كان يبول قائمًا فلا تصدقوه، ما كان يبول إلا قاعدًا) رواه أحمد بن حنبل والترمذي والنسائي وآخرون وإسناده جيد. وقد روي في النهي عن البول قائمًا أحاديث لا تثبت، ولكن حديث عائشة هذا ثابت فلهذا قال العلماء: يكره البول قائمًا إلا لعذر، وهي كراهة تنزيه لا تحريم. قال ابن المنذر في الإشراف: اختلفوا في البول قائمًا: فثبت عن عمر بن الخطاب ﵁ وزيد بن ثابت وابن عمر وسهل بن سعد أنهم بالوا قيامًا، قال: وروي ذلك عن أنس وعلي وأبي هريرة ﵃، وفعل ذلك ابن سيرين وعروة بن الزبير. وكرهه ابن مسعود والشعبي وإبراهيم بن سعد، وكان إبراهيم بن سعد لا يجيز شهادة من بال قائمًا. وفيه قول ثالث: أنه كان في مكان يتطاير إليه من البول شيء فهو مكروه، فإن كان لا يتطاير فلا بأس به، وهذا قول مالك. قال ابن المنذر: البول جالسًا أحب إلي وقائمًا مباح، وكل ذلك ثابت عن رسول الله ﷺ. هذا كلام ابن المنذر.`,
        o: `العلماء: يكره البول قائمًا إلا لعذر كراهة تنزيه. وابن مسعود والشعبي وإبراهيم بن سعد: كرهوه (وإبراهيم لا يجيز شهادة من بال قائمًا). ومالك: يكره إن كان يتطاير إليه البول.`,
        s: `(الصلب: أسفل الظهر؛ هذا لا دليل عليه ولا يوجد حديث صحيح يدل على أن النبي ﷺ كان به وجع الصلب وأنه قد فعل ذلك استشفاءً.) وفي الحقيقة أن هذا قد ثبت عنه ﷺ ولسنا نحتاج إلى تكلف وجوه الاحتمالات خصوصًا مع عدم صحة واحد منها، والصحيح الوجه الخامس والذي ذكره جوازًا أنه ﷺ فعله لبيان الجواز، ولا يلزم أن يكون البول قائمًا مكروهًا لكونه ﷺ واظب على البول جالسًا. وحديث عائشة فيه مقال فقد تكلم العلماء على سنده، ولو صح فلا يدل على عدم جواز البول قائمًا لأن هذا حال بوله في المنزل، وهذا الذي رأته عائشة، وأما في طريقه وسفره ﷺ ونحو ذلك وربما كان ماشيًا فقد ثبت أنه بال قائمًا فلا يكره ذلك. والكراهة فيها نظر لأن النهي لم يثبت، والمواظبة على الفعل لا تدل على أن ما سواه مكروهًا خصوصًا مع ثبوت أنه ﷺ بال قائمًا، فيكون البول قاعدًا أفضل لأنه العادة المتكررة ولا يكره البول قائمًا. وعدم إجازة شهادة من بال قائمًا تشدد من غير دليل. وكلام ابن المنذر هو أحسن الأقوال: أنه مباح وليس بمكروه والبول جالسًا أفضل. بالنسبة للبول قائمًا في زماننا في كثير من الأماكن المفتوحة ويضاف إليها أنها لا بد أن تكون في مكان تستر فيه العورة لأن كثيرًا من هذه الأماكن ربما يقع فيه نوع من التساهل في كشف العورة.` },
      { q: `البول في السباطة بقرب الدور، والبول على جدار الغير (الإذن العرفي)`, p: `144–146`,
        n: `وأما بوله ﷺ في سباطة قوم فيحتمل أوجهًا: أظهرها: أنهم كانوا يؤثرون ذلك ولا يكرهونه بل يفرحون به، ومن كان هذا حاله جاز البول في أرضه والأكل من طعامه، ونظائر هذا في السنة أكثر من أن تحصى، وقد أشرنا إلى هذه القاعدة في كتاب الإيمان في حديث أبي هريرة ﵁ قال: (احتفزت كما يحتفز الثعلب). والوجه الثاني: أنها لم تكن مختصة بهم بل كانت بفناء دورهم للناس كلهم فأضيفت إليهم لقربها منهم. والثالث: أن يكونوا أذنوا لمن أراد قضاء الحاجة إما بصريح الإذن وإما بما في معناه. وأما بوله ﷺ في السباطة التي بقرب الدور مع أن المعروف من عادته ﷺ التباعد في المذهب، فقد ذكر القاضي عياض ﵁ أن سببه: أنه ﷺ كان من الشغل بأمور المسلمين والنظر في مصالحهم بالمحل المعروف، فلعله طال عليه مجلس حتى حفزه البول فلم يمكنه التباعد، ولو أبعد لتضرر، وارتاد السباطة لدمثها، وأقام حذيفة بقربه ليستره عن الناس، وهذا الذي قاله القاضي حسن ظاهر.`,
        o: NO_O,
        s: `(أظهرها) فيفرحون بأن النبي ﷺ عاملهم معاملة نفسه في استعمال أشيائهم. والحديث في مسلم: (حدثني أبو هريرة قال: كنا قعودًا حول رسول الله ﷺ معنا أبو بكر وعمر في نفر، فقام رسول الله ﷺ من بين أظهرنا فأبطأ علينا وخشينا أن يقتطع دوننا وفزعنا فقمنا، فكنت أول من فزع فخرجت أبتغي رسول الله ﷺ حتى أتيت حائطًا للأنصار لبني النجار، فدرت به هل أجد له بابًا فلم أجد، فإذا ربيع يدخل في جوف حائط من بئر خارجة — والربيع الجدول — فاحتفزت كما يحتفز الثعلب فدخلت على رسول الله ﷺ فقال: «أبو هريرة» ... «اذهب بنعلي هاتين فمن لقيت من وراء هذا الحائط يشهد أن لا إله إلا الله مستيقنًا بها قلبه فبشره بالجنة»)؛ فالنبي ﷺ دخل حائطًا لأحد الأنصار ودخل وراءه أبو هريرة أيضًا، فدل ذلك على أنه من علم رضى صاحبه باستعمال شيء من أملاكه أو بأخذها جاز له ذلك، فالإذن العرفي كالإذن اللفظي في ذلك. (والوجه الثاني) كأكوام القمامة العامة للناس جميعًا، والأول أظهر لأنه قال: (سباطة قوم). (والثالث) أي أذنوا للجميع وليس للنبي ﷺ فقط. (لدمثها) أي أنها تشرب البول. وربما قيل في التباعد بالغائط لأنه الذي يكون معه الصوت والرائحة التي يُتأذى بها، فكان النبي ﷺ لا يفعل ذلك بقرب الناس وإنما يبعد عنهم وإنما ورد القرب في البول فقط، فينبغي أن يخصص بالبول، بمعنى أن يكون الذي ذكره القاضي من الشغل بأمور المسلمين والنظر في مصالحهم، إذا كان ذلك في قضاء الحاجة في البول فقط. مسألة: لو علم أن الناس لا يرضون أن يبال على جدارهم لم يجز له ذلك إذا كانت مملوكة كما يقع ذلك في كثير من البيوت والطرقات يكره الناس أن يبال على بيوتهم خصوصًا مع تكرر الأمر يؤدي إلى وجود الرائحة الكريهة فلا يجوز مثل هذا الأمر؛ وأما إذا كان ذلك في طريق الناس كان ذلك أشد وأغلظ لأنه يتأذى به المسلمون.` },
      { q: `القرب من البائل والتباعد عنه، وطلب البائل من صاحبه القرب ليستره`, p: `145–146`,
        n: `قال العلماء: إنما استدناه ﷺ ليستتر به عن أعين الناس وغيرهم من الناظرين لكونها حالة يستخفى بها ويستحيى منها في العادة، وكانت الحاجة التي يقضيها بولًا من قيام يؤمن معها خروج الحدث الآخر والرائحة الكريهة، فلهذا استدناه. وجاء في الحديث الآخر لما أراد قضاء الحاجة قال: «تنح» لكونه كان يقضيها قاعدًا ويحتاج إلى الحديثين جميعًا فتحصل الرائحة الكريهة وما يتبعها. ولهذا قال بعض العلماء في هذا الحديث: من السنة القرب من البائل إذا كان قائمًا، فإذا كان قاعدًا فالسنة الإبعاد عنه. وفيه: جواز قرب الإنسان من البائل، وجواز طلب البائل من صاحبه الذي يدل عليه القرب منه ليستره، واستحباب الستر، وجواز البول بقرب الديار، وفيه غير ذلك.`,
        o: NO_O,
        s: `القرب منه من غير نظر بل يعطيه ظهره أو نحوه ليكون أستر له؛ وننبه على أن المراحيض المعاصرة فيها من التقارب ولا يكون أحدهم ساترًا للآخر. («الذي يدل عليه» أي الذي له دلال عليه.)` },
      { q: `البول في القارورة وتشديد أبي موسى، والرذاذ اليسير من البول، والاستبراء`, p: `146–147`,
        n: `مقصود حذيفة أن هذا التشديد خلاف السنة؛ فإن النبي ﷺ بال قائمًا، ولا شك في كون القائم معرضًا للرشيش، ولم يلتفت النبي ﷺ إلى هذا الاحتمال، ولم يتكلف البول في قارورة كما فعل أبو موسى ﵁.`,
        o: `بعض العلماء: لا يعفى عن رذاذ البول ولو مثل رؤوس الإبر.`,
        s: `(والقارورة هي زجاجة لها عنق، فيدخل فيها حتى يأمن من الرذاذ.) والصحيح أن مثل هذا الرذاذ الذي لا يظهر لا حكم له، وقد عد مثله بعض العلماء [مثل رؤوس الإبر من الرذاذ] فهذا الاحتمال غير ظاهر وبالتالي فهو غير معتبر، أما لو شعر به وأدركه بصره أو حسه لزمه أن يغسله، والكلام هنا على غير المدرك، ومثل ذلك كما يكون في أرجل الذباب مثلًا؛ فالذباب قد يقف على غائط أو على بول وينتقل بعد ذلك إلى شيء طاهر، فمثل هذا لا يدرك بالعين، فالعبرة بما يظهر. وقول أبي موسى ﵁: [إن بني إسرائيل كان إذا أصاب جلد أحدهم بول قرضه بالمقاريض] ظاهر هذه الرواية أنهم كانوا مكلفين بذلك، ولم يذكر سنده في ذلك فلعله سمعه من بعضهم، وقد ثبت في الحديث أنهم كان لهم صاحب قال ﷺ: [أو ما علمت ما أصاب صاحب بني إسرائيل كانوا إذا أصابهم شيء من البول قرضوه بالمقاريض فنهاهم صاحبهم فعذب في قبره] (قال الشيخ الألباني: صحيح)، والذي يظهر أن هذا في الثياب إذا أصابها البول فلم يكن مأذونًا لهم في غسلها بل إذا أصابها البول قصوها، وأما الجلد فهذا قول أبي موسى ولعله سمعه من بعضهم، ولا نعلم حديثًا صحيحًا مرفوعًا إلى النبي ﷺ دالًا على أن بني إسرائيل كانوا مكلفين بأن يقرض جلدهم بالمقراض إذا أصابهم البول. وفيه: تيسير الله لهذه الأمة على الاحتمالين سواء كان القص للثوب أو للجلد إذا أصابه البول، فهذا تشديد بلا شك، فمن رحمة الله بهذه الأمة أن أباح لهم الغسل وسبحان الله في ما آل إليه حال الأمتين اليهود والنصارى من عدم الاستنجاء أصلًا فعاداتهم وتقاليدهم أنهم لا يعبؤون بما يصيبهم من البول فالحمد لله على تيسيره وفضله. ولا يعني هذا الحديث التهاون في البول فنترك ما أدركت العين من رشاش البول على ثوبه أو جلده أو يهمل الاستنجاء مثلًا فهذا من أعظم أسباب عذاب القبر، كما قال النبي ﷺ: (استنزهوا من البول فإن عامة عذاب القبر منه)، وحديث: (فسمع صوت إنسانين يعذبان في قبورهما فقال: يعذبان وما يعذبان في كبيرة وإنه لكبير، كان أحدهما لا يستتر من البول). أما المبالغة في ذلك مثل ما يتكلفه البعض من القيام والنتر والقفز عدة مرات لاستخراج ما قد يتبقى لاحتمال ما يخرج، فإن الاحتمالات الغير ظاهرة غير معتبرة.` },
      { q: `الاستعانة في الوضوء: أقسامها وحكم صب الماء على المتوضئ`, p: `147–148`,
        n: `وفي هذا الحديث دليل على جواز الاستعانة في الوضوء، وقد ثبت أيضًا في حديث أسامة بن زيد ﵁ أنه صب على رسول الله ﷺ في وضوئه حين انصرف من عرفة، وقد جاء في أحاديث ليست بثابتة النهي عن الاستعانة. قال أصحابنا: الاستعانة ثلاثة أقسام: أحدها: أن يستعين بغيره في إحضار الماء فلا كراهة فيه ولا نقص. والثاني: أن يستعين به في غسل الأعضاء ويباشر الأجنبي بنفسه غسل الأعضاء فهذا مكروه إلا لحاجة. والثالث: أن يصب عليه فهذا الأولى تركه، وهل يسمى مكروهًا؟ فيه وجهان. قال أصحابنا وغيرهم: وإذا صب عليه وقف الصاب على يسار المتوضئ.`,
        o: `الشافعية: مباشرة الغير غسل الأعضاء مكروه إلا لحاجة، والصب الأولى تركه.`,
        s: `(«لحاجة»: كمرض مثلًا؛ بأن يمد يده وآخر يدلكها له، فليس هذا من عادة النبي ﷺ، والتصريح بالكراهة أيضًا فيه نظر فإن الأحاديث الضعيفة لا يثبت منها حكم الكراهة، ولكن لو قيل خلاف الأولى لأنه خلاف السنة لكان أحسن.) كثير من الفقهاء المتأخرين يذكر كثيرًا من الأحكام مبنية على الأحاديث الضعيفة لقلة بضاعتهم من الحديث كما قالوا، فيأتي من بعدهم وقد عرف ضعف الحديث، ولكنه لا يجسر على مخالفة من سبق؛ مثل الكلام هنا فقد أثبت أن الأحاديث غير صحيحة وغير ثابتة ومع ذلك قال بالكراهة. والصحيح أنه لا يقال عنه (أي الصب) مكروه بل ولا خلاف الأولى لعدم وروده ما يدل على أنه خلاف الأولى إلا ما كان من سؤال الناس، فإنهم إن فعلوه من غير طلب فلا حرج عليه، وإذا طلب منهم فهذا خلاف الأولى لأن النبي ﷺ بايع جماعة من أصحابه ألا يسألوا الناس شيئًا فقال: «من تكفل لي أن لا يسأل الناس شيئًا وأتكفل له بالجنة»، فكان أولئك النفر يسقط سوط أحدهم فما يسأل أحدًا يناوله إياه؛ وذلك من أجل أن الأولى ألا يسأل الناس شيئًا على الإطلاق، فأصل سؤال الناس في الأصل ممنوع. أما استحباب الوقوف على يسار المتوضئ لا نعلم فيه دليلًا صحيحًا.` },
      { q: `إخراج اليد من تحت الجبة، ولبس الملابس المشتركة ولو كانت مصنوعة في بلاد الكفار (التشبه)`, p: `148–149`,
        n: `قوله (فأخرجهما من تحت الجبة) فيه جواز مثل هذا للحاجة وفي الخلوة، وأما بين الناس فينبغي ألا يفعل لغير حاجة لأن فيه إخلالًا بالمروءة.`,
        o: NO_O,
        s: `(الإخلال بالمروءة متفاوت بين الناس في أعرافهم وبلادهم ومبنى ذلك على العرف ولا يقال يكره شيء من ذلك كراهة عامة.) وفيه: جواز لبس الملابس المشتركة وإن كانت مصنوعة في بلاد الكفر وإن كانت خياطتها بوصف معين أعتيد أن يكون في بلاد الكفار، فالجبة الشامية هي الرومية فبلاد الشام وقت إذ كانت للروم وفي رواية البخاري: (جبة رومية ضيقة الكمين) [بل هو في سنن الترمذي (صححها الألباني) وغيره من أصحاب السنن ورواية البخاري (شامية)]. فلبس الملابس المفصلة أو المخيطة على طريقة قوم كفار لا يحرم طالما أن الثياب مشتركة بين المسلمين والكفار، وإنما يحرم وينهى عن التشبه بما كان من خصائصهم، أما الثياب المشتركة فلا ينهى عنها كالسراويل مثلًا، فبعض الناس يقولون هذا البنطلون مفصل على الطريقة الأوروبية وأما العربي فلا بد أن يلبس سروال بطريقة معينة، وليس كذلك فالعبرة ألا يكون فيه ضيق فإن كان ضيقًا فيمنع منه من أجل الضيق وتجسيم العورة، وأما إذا كان واسعًا فلا حرج أن يكون مخيطًا على أي طريقة، طالما أنه من الثياب المشتركة ومعلوم أنه من الثياب المشتركة.` },
      { q: `اشتراط لبس الخفين على طهارة كاملة، ومعنى «فإني أدخلتهما طاهرتين»`, p: `149–150`,
        n: `قوله ﷺ: «فإني أدخلتهما طاهرتين» فيه دليل على أن المسح على الخفين لا يجوز إلا إذا لبسهما على طهارة كاملة بأن يفرغ من الوضوء بكماله ثم يلبسهما؛ لأن حقيقة إدخالهما طاهرتين أن تكون كل واحدة منهما أدخلت وهي طاهرة. وقد اختلف العلماء في هذه المسألة: فمذهبنا أنه يشترط لبسهما على طهارة كاملة، حتى لو غسل رجله اليمنى ثم لبس خفها ثم غسل اليسرى ثم لبس خفها لم يصح لبس اليمنى، فلا بد من نزعها وإعادة لبسها، ولا يحتاج إلى نزع اليسرى لكونها ألبست بعد كمال الطهارة، وشذ بعض أصحابنا فأوجب نزع اليسرى أيضًا. وهذا الذي ذكرناه من اشتراط الطهارة في اللبس هو مذهب مالك وأحمد وإسحاق. وقال أبو حنيفة وسفيان الثوري ويحيى بن آدم والمزني وأبو ثور وداود: يجوز اللبس على حدث ثم يكمل طهارته.`,
        o: `أبو حنيفة والثوري ويحيى بن آدم والمزني وأبو ثور وداود: يجوز اللبس على حدث ثم يكمل طهارته.`,
        s: `الحديث يدل على عدم جواز المسح على الخف إلا إذا كان بعد طهارة مائية لأنه ﷺ قال: (فإني أدخلتهما طاهرتين) والطهارة هنا لم تكن نجسة قبل غسلها، وهو رد على من يقول أن هذا لفظ مجمل وأن الطهارة تستعمل استعمالات متعددة وأن المؤمن لا ينجس، فعندما تقول المحدث لا يمس المصحف لأن النبي ﷺ قال: (لا يمس القرآن إلا طاهر) فيقولون [طاهر] لفظ مجمل، بل الظاهر عند الإطلاق الطهارة الكاملة من الحدث والنجس، ولذلك نقول الأصل في الطهارة الطهارة الكاملة، وهنا قوله (فإني أدخلتهما طاهرتين) مع أحاديث التوقيت يدل على أن المقصود بالطهارة الطهارة المائية، فلا يصح أن يمسح على خف لبسه على تيمم لأنه خص رجليه ولم يصف بدنه كله بالطهارة، فهنا لا بد أن تكون طهارة تامة لهذين العضوين ومعلوم أن التيمم لا تدخل فيه القدمان فلا تكون طهارة إلا حكمًا، وهنا خصص القدمين (فإني أدخلتهما طاهرتين) إذًا فلا بد أن تكون طهارة لهما بالذات فتكون الطهارة بالماء، وقلنا مع أحاديث التوقيت لأن المسح له وقت معين لا يجوز له أن يكرر المسح لأن الرجل تحتاج إلى الغسل وهو دليل على أن طهارة الرجل التامة الكاملة إنما تكون بالماء. ولأنها إلى انتهاء الوضوء فإن الحدث ما زال متعلقًا بالإنسان فاكتمال الطهارة من الحدث لا تكمل للأعضاء إلا بعد اكتمال الوضوء، وعلى هذا فلو لبس اليمنى قبل انتهاء الوضوء، فتكون هذه القدم اليمنى لم تزل عنها حكم الحدث. والقول الأول (اشتراط الطهارة الكاملة قبل اللبس) هو الصحيح لهذا الحديث.` },
    ],
  },
  {
    title: `باب المسح على الناصية والعمامة (ص151–156)`,
    items: [
      { q: `مسح بعض الرأس والتكميل على العمامة، والمسح على خف مخرق`, p: `152–153`,
        n: `قوله (مسح بناصيته وعلى العمامة) هذا مما احتج به أصحابنا على أن مسح بعض الرأس يكفي، ولا يشترط الجميع؛ لأنه لو وجب الجميع لما اكتفى بالعمامة عن الباقي، فإن الجمع بين الأصل والبدل في عضو واحد لا يجوز، كما لو مسح على خف واحد وغسل الرجل الأخرى. وأما التتميم بالعمامة فهو عند الشافعي وجماعة على الاستحباب لتكون الطهارة على جميع الرأس، ولا فرق بين أن يكون لبس العمامة على طهر أو على حدث، وكذا لو كان على رأسه قلنسوة ولم ينزعها مسح بناصيته، ويستحب أن يتم على القلنسوة كالعمامة.`,
        o: NO_O,
        s: `وهذا (عدم جواز غسل بعض الرجل ومسح الباقي) عند عامة العلماء، كما أنه لا يجوز أن يغسل بعض الرجل إذا كانت بادية في خف مخرق أو ناقص ويمسح على الجزء الباقي باتفاق العلماء، فلا بد أن يكون الخف ساترًا لمحل الفرض والخروق اليسيرة لا تضر، ولكن لو كانت على سبيل المثال أصابع قدمه بادية كالشرابات الطبية فهذا ليس بخف ولا يسمى خفًّا فلا يجوز له أن يغسل أطراف الأصابع ثم يمسح على الباقي باتفاق العلماء. ولكن الكلام في مسألة الخروق: فإذا كان الخف مخرق خروق يسيرة لا تخرجه عن وصفه خفًّا فقد قال الحسن: (لم تكن تسلم خفافهم من الخروق) وهذا كلام صحيح، فالخرق اليسير لا يضر ولا يلزم أن يكون ساترًا لمحل الفرض بمعنى أنه لا يبدو منه شيء ولو كان يسيرًا. فهذا القياس (الجمع بين الأصل والبدل) قياس قوي من جهة المعنى فإنه إذا كان قد مسح على الناصية والعمامة فهذا يدل على جواز مسح بعض الرأس، ولكن ليس هو السنة أن يمسح بعض الرأس مكتفيًا به بل السنة أن يمسح بعض الرأس متممًا الباقي على العمامة، وهذا يجوز للرجل وللمرأة لحاجة ولغير حاجة.` },
      { q: `شروط المسح على العمامة والخمار والقلنسوة، والاقتصار على العمامة دون الناصية`, p: `153–154`,
        n: `ولو اقتصر على العمامة ولم يمسح شيئًا من الرأس لم يجزه ذلك عندنا بلا خلاف، وهو مذهب مالك وأبي حنيفة وأكثر العلماء ﵏. وذهب أحمد بن حنبل — رحمه الله تعالى — إلى جواز الاقتصار، ووافقه عليه جماعة من السلف.`,
        o: `الشافعي ومالك وأبو حنيفة وأكثر العلماء: لا يجزئ الاقتصار على العمامة.`,
        s: `(«ولا فرق بين أن يكون لبس العمامة على طهر أو على حدث»: لأنها تتمة ولا يقاس على الخف في كل الأشياء، إنما يقاس على الخف على قول الإمام أحمد — خلافًا للجمهور — إذا ما مسح على العمامة والخمار فقط فيشترط في هذه الحالة ألا يمسح شيء من الناصية أو الرأس وأن يمسح على العمامة أو الخمار كله وينطبق نفس الشروط اللازمة للمسح على الخف من: [تغطية محل الفرض — لبس على طهارة — التوقيت]؛ وهذا على مذهب الإمام أحمد الذي يجوز المسح على العمامة فقط خلافًا للجمهور وسيأتي الكلام عليه وفيه حديث بلال: (أنه مسح على الخفين والخمار) فظاهره أنه مسح على الخمار فقط، وهو حديث آخر غير حديث المغيرة ولا يصح أن نقول تحمل هذا على هذا لأن كل منها مستقل، فهذه وقائع مختلفة، فظاهر هذا أنه مسح على العمامة فقط، فهنا قياسًا على الخف، فهنا لا بد أن تكون العمامة تغطي كل شعر رأسه، ولبست على طهارة، ولبست يوم وليلة للمقيم وثلاثة أيام ولياليهن للمسافر، بخلاف المسح على العمامة مع الناصية فلا يلزم أن يلبسها على طهارة ولا يلزم أن تغطي محل الفرض فتصلح القلنسوة لأن الطاقية التي نلبسها تكون كاشفة جزء من محل الفرض من جانبي ومؤخر الرأس وأحيانًا من الناصية فلا مانع من أن يمسح عليها مع الناصية ولكن يمنع من المسح عليها منفردة دون مسح على شيء من الرأس، ولا يشترط المدة إذا مسح على الناصية والعمامة.) وقسنا على الخف لأنه وارد مثله فالأصل (وامسحوا برؤوسكم) فإذا ثبت الدليل من السنة أنه مسح على العمامة فالعضو الممسوح إذا كان بدلًا عن المغسول أو الممسوح نفسه (أي على المسح على الممسوح ولكن بدون مباشرة) فينبغي أن يكون مثله في الأحكام. والراجح هو إجزاء مسح جزء من الرأس، ولكن لكي يأخذ الفضيلة يتمم بالمسح على العمامة، ومسح كل الرأس هو السنة. ويجزيء مسح بعض الرأس بدون شيء مباشر له وليس المسح على العمامة التي على الرأس. والمسح على العمامة فقط مخصصة لظاهر القرآن (وامسحوا برؤوسكم) فيلزم مسح رأسه وليس العمامة ولا القلنسوة التي على رأسه، فنحن سوف نخصص جواز ذلك بالسنة (بأنه مسح على الخفين والخمار) فيقوم مقام المسح على الرأس المسح على العمامة مثل ما قام مقام غسل الرجلين المسح على الخفين فتأخذ نفس الأحكام. فإذا لم يمسح على الناصية فليمسح على العمامة كلها أو على الخمار كله، والخمار هو غطاء الرأس. والمرأة تمسح على الخمار إلى أول القفا، والاحتياط خروجًا من الخلاف فالجمهور يمنع من الاقتصار على المسح على الخمار فلو مسح جزء من الناصية وتمت على الخمار يكون هذا خروجًا من الخلاف وهذا هو الأحوط، ولكن مذهب الإمام أحمد يجوز المسح على العمامة أو الخمار فقط وهذا هو الراجح لحديث بلال الذي سيأتي. وقلنا الشروط عندهم هي شروط المسح على الخفين في تلك الحالة.` },
      { q: `فوائد حديث صلاة عبد الرحمن بن عوف بالناس: اقتداء الفاضل بالمفضول، وتقديم الصلاة أول الوقت، وتأخر الإمام الراتب`, p: `154–155`,
        n: `اعلم أن هذا الحديث فيه فوائد كثيرة: منها جواز اقتداء الفاضل بالمفضول، وجواز صلاة النبي ﷺ خلف بعض أمته. ومنها: أن الأفضل تقديم الصلاة في أول الوقت فإنهم فعلوها أول الوقت ولم ينتظروا النبي ﷺ. ومنها: أن الإمام إذا تأخر عن أول الوقت استحب للجماعة أن يقدموا أحدهم فيصلي بهم إذا وثقوا بحسن خلق الإمام وأنه لا يتأذى من ذلك ولا يترتب عليه فتنة، فأما إذا لم يأمنوا أذاه فإنهم يصلون في أول الوقت فرادى، ثم إن أدركوا الجماعة بعد استحب لهم إعادتها معهم.`,
        o: NO_O,
        s: `فالنبي ﷺ اقتدى بعبد الرحمن بن عوف ﵁، وهذه فضيلة لعبد الرحمن بن عوف ﵁ أن النبي ﷺ صلى خلفه. ولم ينتظروا النبي ﷺ لأنهم لم يعلموا متى يأتي فقد تخلف عنهم. فهنا أمرين للإمام: الوثوق بحسن خلقه: أي عندما يأتي لا يشاكلهم ويشاحنهم، وثانيًا: ألا يتأذى، فربما يكون حسن الخلق ولكن يؤذيه ذلك فعليهم أن ينتظروا. وهذا الكلام في وقت الفضيلة كله طالما أنه باقي فينتظر الإمام حتى ينتهي وقت الفضيلة ويصلوا فرادى لقوله ﷺ: (ولا يؤمن الرجل الرجل في سلطانه ولا يقعد في بيته على تكرمته إلا بإذنه) فالإمام الراتب سلطان في محله، فلو صلوا بآخر فقد صلوا بغير إذنه، أما إذا كان بإذنه فقد قام مقامه فكأنه استخلفه فقام فصلى مكانه، ففي هذه الحالة فهم معذورون بصلاتهم فرادى وعن الجماعة مثل الصحابي الذي انصرف عن الجماعة وصلى منفردًا لما طول معاذ في الصلاة فهذا عذر عن الجماعة في تلك الحال. وتقدم عبد الرحمن للصلاة وعدم انتظار النبي ﷺ لأنهم علموا أنه ولما أتى صلى خلفه وهذا دليل أنه رضي بفعلهم فعلموا ذلك من عادته ﷺ ومثله عندما تأخر عن الوقت المعتاد كان بلال أقيم الصلاة فصلى بالناس وصلى أبو بكر ﵁ فهذا دليل على أن النبي كان له عادة في أغلب الأحوال كان يصلي فيها فإذا تأخر عنها قدموا غيره يصلي بهم.` },
      { q: `المسبوق: ما يسقط عنه وما لا يسقط (الفاتحة والقيام)، ومتابعته الإمام، ومتى يفارقه`, p: `155`,
        n: `ومنها: أن من سبقه الإمام ببعض الصلاة أتى بما أدرك، فإذا سلم الإمام أتى بما بقي عليه ولا يسقط ذلك عنه، بخلاف قراءة الفاتحة فإنها تسقط عن المسبوق إذا أدرك الإمام راكعًا. ومنها: اتباع المسبوق للإمام في فعله في ركوعه وسجوده وجلوسه وإن لم يكن ذلك موضع فعله للمأموم. ومنها: أن المسبوق إنما يفارق الإمام بعد سلام الإمام.`,
        o: `الشافعية والجمهور: تسقط الفاتحة عن المسبوق إذا أدرك الإمام راكعًا.`,
        s: `هذا عند الشافعية والجمهور ولكن الراجح أنها لا تسقط أيضًا لأنها ركن والقيام ركن فلا بد أن يأتي بها فإذا فاته القيام والقراءة لم يدرك الركعة. وهذه وإن كانت غير ظاهرة من هنا ولكن تابعوه على التشهد الأخير [فلما سلم قام النبي ﷺ وقمت فركعنا الركعة التي سبقتنا] إذًا فالنبي ﷺ تبعهم في الجلوس في التشهد الأخير، فدل ذلك على أنه يتابعه في فعله حتى ولو كان هذا موضع فعله، ولذلك فإنه ينزل ساجدًا مباشرة إذا كان الإمام ساجدًا ثم يكمل بعد ذلك مع الإمام. وظاهرها (يفارقه بعد سلامه) عندنا سلم التسليمتين.` },
      { q: `الفرق بين تأخر أبي بكر ليتقدم النبي ﷺ وبقاء عبد الرحمن بن عوف، وحكم الاستخلاف إذا خرج الإمام من الصلاة`, p: `155`,
        n: `وأما بقاء عبد الرحمن في صلاته وتأخر أبي بكر الصديق ﵁ ليتقدم النبي ﷺ فالفرق بينهما: أن في قضية عبد الرحمن كان قد ركع ركعة فترك النبي ﷺ التقدم لئلا يختل ترتيب صلاة القوم بخلاف قضية أبي بكر ﵁.`,
        o: NO_O,
        s: `وهذا دليل على أنه إذا كان يأتم بمن يحصل خلل في الصلاة بالاقتداء به فلا ينبغي أن يفعل، بمعنى أن الإمام لو حدث له طارق فخرج من الصلاة لانتقاض وضوئه فلا يقدم للمأمومين مسبوقًا حتى لا يختل نظام متابعة الإمام؛ ولا يصلي فريضة خلف من يصلي صلاة الكسوف لأن هذا يؤدي إلى خلل في الأركان.` },
    ],
  },
  {
    title: `باب التوقيت في المسح على الخفين (ص157–159)`,
    items: [
      { q: `توقيت المسح على الخفين (يوم وليلة للمقيم وثلاثة أيام للمسافر)، ومفهوم المخالفة`, p: `158`,
        n: `ففيه الحجة البينة والدلالة الواضحة لمذهب الجمهور: أن المسح على الخفين موقت بثلاثة أيام في السفر ويوم وليلة في الحضر، وهذا مذهب أبي حنيفة والشافعي وأحمد وجماهير العلماء من الصحابة فمن بعدهم. وقال مالك في المشهور عنه: يمسح بلا توقيت، وهو قول قديم ضعيف عن الشافعي، واحتجوا بحديث ابن عمارة بكسر العين في ترك التوقيت رواه أبو داود وغيره وهو حديث ضعيف باتفاق أهل الحديث. وأوجه الدلالة من الحديث على مذهب من يقول بالمفهوم ظاهرة، وعلى مذهب من لا يقول به يقال: الأصل منع المسح فيما زاد.`,
        o: `مالك في المشهور عنه والشافعي في القديم: يمسح بلا توقيت.`,
        s: `فيفهم منها أنه لا يزيد على ذلك، وأن ما زاد عليها بخلافها. وأبو حنيفة لا يأخذ بمفهوم المخالفة خلافًا للجمهور؛ فيأتي بها من دليل أنها رخصة خلاف الأصل، والأصل وجوب الغسل والمسح ورد كرخصة فإذا ورد مدة، فإنه ما زاد عليها يكون ممنوعًا منه والذي يحتاج أن يأتي بالدليل هو الذي يقول بالزيادة.` },
      { q: `ابتداء مدة المسح: من الحدث أم من المسح؟`, p: `158`,
        n: `ومذهب الشافعي وكثيرين: أن ابتداء المدة من حين الحدث بعد لبس الخف، لا من حين اللبس ولا من حين المسح، ثم إن الحدث عام مخصوص بحديث صفوان بن عسال ﵁ قال: (أمرنا رسول الله ﷺ إذا كنا مسافرين أو سفرًا أن لا ننزع خفافنا ثلاثة أيام ولياليهن إلا من جنابة).`,
        o: `الشافعي وكثيرون: تبدأ المدة من الحدث بعد اللبس.`,
        s: `والصحيح والله أعلم أنه يمسح ثلاثة أيام، فالصحيح أن الحدث لا حكم له بدون المسح وإنما يبدأ التوقيت بالمسح، فأصح الأقوال في ذلك أن بداية التوقيت في اليوم والليلة للحاضر وثلاثة أيام ولياليهن للمسافر بأول مسحة بعد الحدث لظاهر الحديث؛ فإذا توضأ مثلًا في الفجر ثم مسح خفيه وظل على وضوئه وأحدث مثلًا بعد الظهر ثم مسح في أول الوضوء في العصر، فعلى هذا يمسح من العصر في اليوم الذي يليه، والظاهر أن المدة المقصود بها في توقيت المسح أيضًا وليس في انتقاض الوضوء بانقضائها، فإنه وقت له في المسح بثلاثة أيام أو يوم وليلة، فإذا انقضت المدة منع المسح وليس أنه ينتقض الوضوء فوضوؤه باقي لأنه قد وقع صحيحًا مأذونًا فيه، فنستصحب بقاء الوضوء وصحته إلى أن يأتي دليل — يقتضي نقض الوضوء ولم يأت — يخرجه عن هذا الأصل، وإنما الدليل في منع المسح بعد ذلك. فيكون مقصود بالحدث هو الحدث الأصغر وليس الحدث الأكبر، وأما في الجنابة فلا بد من نزع الخف فيها وغسل الرجلين.` },
      { q: `الجنابة قبل انقضاء المدة، وتنجس الرجل داخل الخف`, p: `159`,
        n: `قال أصحابنا: فإذا أجنب قبل انقضاء المدة لم يجز المسح على الخف، فلو اغتسل وغسل رجليه في الخف ارتفعت جنابته وجازت صلاته، فلو أحدث بعد ذلك لم يجز له المسح على الخف بل لا بد من خلعه ولبسه على طهارة، بخلاف ما لو تنجست رجله في الخف فغسلها فيه، فإن له المسح على الخف بعد ذلك.`,
        o: NO_O,
        s: `بمعنى أنه يغسلها فيدخل الماء إلى قدمه وهي في الخف بحيث تعم رجليه، فإذا كان كذلك فقد صح أنه غسل رجليه، ولكن لم يلبس الخف على طهارة، فعليه أن يخلعه ويلبسه مرة ثانية في ساعته. وأما النجاسة: فهو قد أزال النجاسة وكان قد لبس الخف على طهارة من الحدث، فتكون طاهرتين من الحدث المقصود بها الحدث أن تكون طاهرتين من الحدث لا من النجس، فلو كان في رجله نجاسة فأزالها وهو كان قد لبس الخف على طهارة جاز له أن يمسح، وهذا مأخوذ من اشتراط اللبس على طهارة.` },
      { q: `نزع الخف بعد المسح وهو على طهارة: هل ينتقض الوضوء؟ (مسألة)`, p: `159`,
        n: NO_N, o: NO_O,
        s: `مسألة: وهو أنه لو نزع الخف وهو على طهارة بعد مسحه فهل ينتقض وضوؤه بذلك أم يكفي غسل رجليه أم يظل على طهارته؟ الحجة مع من قال يظل على طهارته لأنه يستصحب أيضًا بقاء الطهارة، ولم يأت دليل يدل على فساد هذا الوضوء أو بطلان هذه الطهارة لأنه قد توضأ وضوءًا شرعيًّا صحيحًا، ونزع الخف لم يرد ما يدل على أنه ناقض. وهل بعد النزع يمكن لبس الخف مرة أخرى وتكميل المدة لو كان بها شيء في خفه وأراد إخراجه.` },
      { q: `أدب المسؤول: إرشاد السائل إلى من هو أعلم منه`, p: `159`,
        n: `وفي هذا الحديث من الأدب ما قاله العلماء: إنه يستحب للمحدث وللمعلم والمفتي إذا طلب منه ما يعلمه عند أجل منه أن يرشد إليه، وإن لم يعرفه قال: اسأل عنه فلانًا. قال أبو عمر بن عبد البر: واختلف الرواة في رفع هذا الحديث ووقفه على علي، قال: ومن رفعه أحفظ وأضبط.`,
        o: NO_O,
        s: `أي أنه لو يعلم أن حكم هذه المسألة عند رجل أعلم منه وأفضل أن يرشد إليه؛ لقول عائشة ﵂: (ائت عليًّا فإنه أعلم بذلك مني) فكانت عندها علم ومع ذلك أرشدت إلى علي ﵁.` },
    ],
  },
  {
    title: `باب جواز الصلوات كلها بوضوء واحد (ص160–163)`,
    items: [
      { q: `جواز الصلوات بوضوء واحد، وهل يجب الوضوء لكل صلاة؟`, p: `160–161`,
        n: `في هذا الحديث أنواع من العلم منها: جواز المسح على الخف، وجواز الصلوات المفروضات والنوافل بوضوء واحد ما لم يحدث، وهذا جائز بإجماع من يعتد به. وحكى أبو جعفر الطحاوي وأبو الحسن بن بطال في شرح صحيح البخاري عن طائفة من العلماء أنهم قالوا: يجب الوضوء لكل صلاة وإن كان متطهرًا، واحتجوا بقول الله تعالى: ﴿إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ﴾ الآية. وما أظن هذا المذهب يصح عن أحد، ولعلهم أرادوا استحباب تجديد الوضوء عند كل صلاة. ودليل الجمهور الأحاديث الصحيحة: منها هذا الحديث، وحديث أنس في صحيح البخاري، وحديث سويد بن النعمان في صحيح البخاري أيضًا، وفي معناه أحاديث كثيرة كحديث الجمع بين الصلاتين بعرفة والمزدلفة وسائر الأسفار والجمع بين الصلوات الفائتات يوم الخندق وغير ذلك، وأما الآية الكريمة فالمراد بها — والله أعلم — إذا قمتم محدثين. وقيل: إنها منسوخة بفعل النبي ﷺ، وهذا القول ضعيف.`,
        o: `طائفة (حكاه الطحاوي وابن بطال): يجب الوضوء لكل صلاة. وقيل: الآية منسوخة بفعل النبي ﷺ.`,
        s: `كل هذه الأدلة دلت على أن الآية معناها (إذا قمتم إلى الصلاة وكنتم محدثين). والقول بالنسخ ضعيف لعدم العلم بالتاريخ وقبل ذلك لإمكان الجمع، فيمكن الجمع بتقدير هذا المعنى الثابت في الأحاديث الصحيحة، فبدل من أن تقول (إذا قمتم إلى الصلاة أي قيام) تقول (إذا قمتم محدثين) فتخصص الآية بالقيام محدثًا — حال كونه محدثًا — نعم الآية ظاهرها العموم ولكن الأدلة دلت على تخصيصها لأن هذا واجب في المحدث.` },
      { q: `تجديد الوضوء: شروط استحبابه، وتجديد الغسل والتيمم`, p: `161–162`,
        n: `قال أصحابنا: ويستحب تجديد الوضوء، وهو أن يكون على طهارة ثم يتطهر ثانيًا من غير حدث، وفي شرط استحباب التجديد أوجه: أحدها: أنه يستحب لمن صلى به صلاة سواء كانت فريضة أو نافلة. والثاني: لا يستحب إلا لمن صلى فريضة. والثالث: يستحب لمن فعل به ما لا يجوز إلا بطهارة كمس المصحف وسجود التلاوة. والرابع: يستحب وإن لم يفعل به شيئًا أصلًا بشرط أن يتخلل بين التجديد والوضوء زمن يقع بمثله تفريق. ولا يستحب تجديد الغسل على المذهب الصحيح المشهور، وحكى إمام الحرمين وجهًا أنه يستحب. وفي استحباب تجديد التيمم وجهان: أشهرهما لا يستحب، وصورته في الجريح والمريض ونحوهما ممن يتيمم مع وجود الماء، ويتصور في غيره إذا قلنا لا يجب الطلب لمن تيمم ثانيًا في موضعه.`,
        o: `الأوجه الأربعة عند الشافعية، ووجه حكاه إمام الحرمين باستحباب تجديد الغسل.`,
        s: `(الوجه الأول) أي يستحب لمن صلى صلاة فريضة أو نافلة أن يتوضأ، بمعنى أن رجل متوضئ صلى ركعتين سنة يذهب ويتوضأ ويصلي ركعتين سنة أخرين ثم يتوضأ ويصلي ركعتين فهذا لم يرد عن النبي ﷺ وإنما كان يتوضأ لكل صلاة، الظاهر أنها لكل صلاة مفروضة، فعن أنس قال: [كان النبي ﷺ يتوضأ عند كل صلاة، قلت: كيف كنتم تصنعون؟ قال: يجزئ أحدنا الوضوء ما لم يحدث] (عند كل صلاة) أي مفروضة؛ فيصلي بوضوئه الفريضة بنوافلها. والوجه الثاني (لا يستحب إلا لمن صلى فريضة) هو الصحيح. والوجه الرابع: هذا الكلام فيه نظر فليس عليه دليل، والتفريق يقصد به أن مرده إلى العرف، مثل من يشترط الموالاة بمعنى أن الأعضاء تغسل مع بعضها، وقلنا أن اشتراط الموالاة هو الراجح لأن الآية جمعت بينها فلا بد أن يغسلها مع بعضها، وهذا الأمر طالما لم يحدد فمرده إلى العرف، ولا يصح توقيت الفاصل بجفاف الأعضاء لعدم الدليل ولأجل أن هذا أيضًا فيه تفاوت، ولكن الأمر طالما لم يحدد فمرده إلى العرف. فيقولون لو عرفًا كان الفاصل طويلًا فكل ما يطول الفاصل يذهب ويتوضأ، وهذا كما ذكرنا لا دليل عليه، فالصحيح والله أعلم ما دل عليه حديث أنس ﵁ يتوضأ عند كل صلاة، فالمقصود صلاة الفريضة بنوافلها، لأنه ﷺ كان يصلي مثلًا في قيام الليل عشر ركعات مثنى مثنى ويوتر بواحدة أو اثني عشر ركعة ويوتر بواحدة، وكان النبي ﷺ إذا دخل بيته صلى النافلة ولم يرد أنه ﷺ توضأ إذا دخل بيته للنافلة الراتبة؛ فالأظهر والله أعلم القول الثاني أنه يستحب إلا لمن صلى فريضة. ومعنى تجديد الغسل أي تجديده من غير حاجة وإنما ليأخذ الثواب على ظنه، والراجح عدم الاستحباب لأن الغسل إنما يشرع عند وجود سببه والوضوء يشرع لكل صلاة. وأما التيمم: بمعنى هل يجب مع كل وقت صلاة أن يعيد الطلب؟ فمن قال يجب أن يعيد الطلب يقول: يجب أن يتيمم من جديد، والصحيح أنه لا يستحب التيمم حتى لو قلنا بعدم وجوب الطلب، وهو لا يجب عليه الطلب إلا إذا احتمل الأمر عنده وجود الماء، أما إذا غلب على ظنه عدم وجود الماء لعدم وجود قرينة تدل على عدم تغير الحال لا يلزمه أن يطلب، لأنه قال: (فلم تجدوا ماء فتيمموا) فالعبرة بغلبة الظن. والراجح أنه لا يلزمه أن يتيمم إلا إذا انتقض وضوؤه فلا يلزمه أن يتيمم لكل فريضة.` },
      { q: `مخالفة النبي ﷺ لعادته لبيان الجواز، وسؤال المفضول الفاضل عن بعض أعماله`, p: `162`,
        n: `وأما قول عمر ﵁: (صنعت اليوم شيئًا لم تكن تصنعه) ففيه تصريح بأن النبي ﷺ كان يواظب على الوضوء لكل صلاة عملًا بالأفضل، وصلى الصلوات في هذا اليوم بوضوء واحد بيانًا للجواز كما قال ﷺ: «عمدًا صنعته يا عمر». وفي هذا الحديث: جواز سؤال المفضول الفاضل عن بعض أعماله التي في ظاهرها مخالفة للعادة؛ لأنها قد تكون عن نسيان فيرجع عنها، وقد تكون تعمدًا لمعنى خفي على المفضول فيستفيده.`,
        o: NO_O,
        s: `لأنه من هنا علمه النبي ﷺ جواز الصلوات كلها بوضوء واحد، وأنه ﷺ فعل ما هو خلاف عادته التي هي الأولى من أجل ما هو أفضل وأولى وهو تعليم الناس، والنبي ﷺ قد يفعل بعض ما هو خلاف الأولى عند الإطلاق لأن هذا هو الأولى في حقه ﷺ لبيان الجواز، كما أنه قد يفعل ما قد يكون مكروهًا في حق غيره وقد نهى عنه ﷺ وفعله ﷺ لبيان الجواز وعدم التحريم فيكون في حقه ﷺ هو الأفضل وينبغي أن يفعله ليعلم الناس، بخلاف غيره كما ورد في الشرب قائمًا وقد ثبت النهي عنه وثبت ما يدل على كراهته ومع ذلك فعله النبي ﷺ.` },
    ],
  },
  {
    title: `باب كراهة غمس المتوضئ وغيره يده المشكوك في نجاستها في الإناء قبل غسلها ثلاثًا (ص163–171)`,
    items: [
      { q: `علة الأمر بغسل اليد عند الاستيقاظ: احتمال النجاسة أم مبيت الشيطان (أمر تعبدي)؟`, p: `164–165`,
        n: `قال الشافعي وغيره من العلماء — رحمهم الله تعالى — في معنى قوله ﷺ «لا يدري أين باتت يده»: أن أهل الحجاز كانوا يستنجون بالأحجار وبلادهم حارة، فإذا نام أحدهم عرق فلا يأمن النائم أن يطوف يده على ذلك الموضع النجس أو على بثرة أو قملة أو قذر غير ذلك.`,
        o: NO_O,
        s: `هذه أحد المعاني المحتملة، وهناك معنى آخر وهو معنى غيبي وهو احتمال أن يبيت الشيطان على يده فيكون غسل اليد لغسل أثر بيات الشيطان، فقد قال النبي ﷺ في الاستنشاق والاستنثار عند القيام من النوم: [إذا استيقظ — أراه — أحدكم من منامه فتوضأ فليستنثر ثلاثًا فإن الشيطان يبيت على خيشومه] البخاري. ومن هنا كان هذا أمرًا تعبديًّا لأنه مردود إلى أمر غيبي غير ظاهر، حتى ولو كانت يده في قفاز أو ملفوفة في خرقة وهو على يقين من أنها لم تصب نجاسة فهذا الأمر التعبدي وهو لأجل أن الشيطان كما يبيت على الخيشوم فربما كان يبيت على اليد، فنحن نمتثل ما أمر به النبي ﷺ حتى ولو علمنا أنها لم تصب نجاسة لأن الأمر الغيبي محتمل.` },
      { q: `الماء القليل إذا وردت عليه نجاسة لم تغيره، والفرق بين ورود الماء على النجاسة وورودها عليه (حديث القلتين)`, p: `165–166`,
        n: `وفي هذا الحديث دلالة لمسائل كثيرة في مذهبنا ومذهب الجمهور: منها أن الماء القليل إذا وردت عليه نجاسة نجسته وإن قلت ولم تغيره، فإنها تنجسه؛ لأن الذي تعلق باليد ولا يرى قليل جدًّا، وكانت عادتهم استعمال الأواني الصغيرة التي تقصر عن قلتين بل لا تقاربها. ومنها: الفرق بين ورود الماء على النجاسة وورودها عليه، وأنها إذا وردت عليه نجسته وإذا ورد عليها أزالها.`,
        o: `الشافعية والجمهور: الماء القليل ينجس بمجرد ملاقاة النجاسة، ويفرقون بين وروده عليها وورودها عليه. ومذهب الحنابلة المشهور: العمل بحديث القلتين.`,
        s: `ليس في هذا الحديث دلالة على هذا المدعاه، أولًا: هم لا يقولون بمقتضى الحديث من لزوم غسل اليد بل قالوا إذا فعل ولم يغسل يده وخالف النهي وأدخل يده في الإناء صحت طهارته وصح وضوؤه، وإنما يحملون الحديث على الكراهة، كأنهم يقولون نحن نستصحب الأصل وهو الطهارة، فمن أين النجاسة القليلة تنجس الماء؟ [لا يدري أين باتت يده]، وإنما هذا المنع من استقذار الماء وخصوصًا أنه ذكر من البثرة والقملة فربما أدى ذلك إلى تقذير الماء ولو لم يكن هناك نجاسة؛ فهناك علل متعددة وليس من أجل أن الماء القليل يتنجس بورود قليل النجاسة التي لا ترى عليه، فإنه (لا يدري فيم باتت يده) فلا يرى نجاسة ظاهرة، فلا دلالة في الحديث على أن هذه النجاسة الغير ظاهرة والتي لا ترى والتي هي قليل جدًّا تنجس الماء وأنتم لا تقولون بذلك. وأما الفرق بين ورود الماء على النجاسة وورودها عليه فهذا كلام الشافعية دون غيرهم، وقد التزموا هذا الفرق الذي لا معنى له لأنه يحصل اختلاط بين النجاسة وبين الماء على الحالين، وقد التزموا هذا الفرق لأنهم التزموا أولًا أن الماء القليل إذا أصابته نجاسة تنجس، ومعلوم أن الاستنجاء يكون قطعًا بماء أقل من القلتين (والقلتين مثل الزير الكبير)، فكيف يستخدم كل ذلك في الاستنجاء؟ فمعلوم أن هذا لا يقع مثل ذلك، وإنما سيستخدم ماء قليل، إذًا لا بد أن يختلط الماء القليل هذا بالنجاسة — وهو أثر البول والغائط — وحتى لو تنجس الماء لصار مزيلًا للنجاسة، فيه سوف تتنجس والماء كله أصبح نجسًا حتى ولو لم يوجد أثر في التغير، وبالتالي كل موضع أصابه ذلك الماء لكان نجسًا، إذًا سيصبح من المستحيل أن يتطهر أحد؛ ولهذا التزموا أن ورود الماء على النجاسة لا ينجس الماء وأن ورود النجاسة على الماء ينجسه، وهذا فرق غير ظاهر، فالأليق أن يقال إن هذا الأمر تعبدي، وليس أن تعلل به الأحكام الظاهرة. ولكن على مذهب مالك رحمه الله لا حاجة إلى هذا القول لأن الاثنين فيهم اختلاط ولكن يمكن أن نقول كما قال مالك: [أن اختلاط الماء القليل بالنجاسة التي لا تغيره لا تنجسه بل يبقى على طهوريته] وبالتالي لا نحتاج إلى هذه الفروق الغير ظاهرة والتي لا دليل عليها، فكما ذكرنا فإن الحديث لم يجزم بالنجاسة وإنما أمر النبي ﷺ بصب الماء ليس لأجل هذا الفرق بل لأجل أن إدخال اليد في الإناء لا شك أنه يقذر الماء عمومًا ويؤدي إلى منع وجه من وجوه الانتفاع به، فيد بها تراب فقط أو بها شحم مثلًا وهناك أشياء طاهرة كثيرة ولكن فيها قذارة وفيها ما ينبغي أن يزيلها الإنسان، فلو وضع يده في الإناء قليلًا أو كثيرًا منع وجوهًا من الانتفاع به، بخلاف ما إذا صب على يده من الإناء، فإنه لا يمتنع وجوه الانتفاع، فلا شك أن ما أمر به ﷺ هو المشروع ولو لم تكن هذه العلة موجودة. القول بأن قليل النجاسة إذا خالط قليل الماء الذي لا يغير هذا الماء هو المذهب المعقول معناه الظاهر من جهة الأدلة المختلفة. وأما حديث القلتين: هذا الحديث جعل الشافعي ومن وافقه يقولون بهذه التفرقة [بين القليل والكثير وبين ورود الماء على النجاسة وورود النجاسة على الماء] فالذي يظهر والله أعلم أنه خرج مخرج الغالب، رغم خلاف في تصحيح الحديث والظاهر صحته (إذا بلغ الماء قلتين لم يحمل الخبث)، مفهوم المخالفة فيه ضعيف وعموم حديث (الماء طهور لا ينجسه شيء) أقوى منه بلا شك، وذلك أن مفهوم المخالفة فيه كما ذكرنا إذا كان الحديث قد خرج مخرج الغالب وهو أن الغالب في أحوال الماء الكثير أنه لا يحمل الخبث ولا يؤثر فيه، فنقول خروج الحديث مخرج الغالب يمنع العمل بمفهومه، فيجعل مفهوم المخالفة فيه ضعيفًا، فلا يلزم أن يكون الماء إذا كان أقل من القلتين أن يحمل — الخبث —، ولذلك اضطروا إلى القول بأن هذا غير معقول المعنى بخلاف تعليله بالتغير فهذا أمر ظاهر معقول المعنى، وأما وجود قطرة من النجاسة على ما هو أقل من القلتين بقطرة — على قول من يقول بالتحديد — فيجعله فرقًا بينها وبين ما إذا وجدت قطرة الماء هذه، فهذا أمر غير معقول المعنى فلا ينبغي تعليل الأحكام بعلة غير معقولة المعنى طالما أمكن تعليلها بعلة معقولة المعنى، وخروجها مخرج الغالب كلام ظاهر، بدليل أنه ربما بلغ الماء قلتين وحمل الخبث كما في الزيادة الضعيفة السند الصحيحة المعنى لحديث: (الماء طهور لا ينجسه شيء) [إلا ما غلب على ريحه وطعمه ولونه] وهو متفق على صحة معناه، وهو أن الماء الكثير إذا تغير بالنجاسة صار نجسًا، فهذا مما لا نزاع فيه بين العلماء فدل ذلك على أن الأغلب أن الماء الكثير لا يحمل النجاسة وقد يحملها والأغلب أن الماء القليل يحمل النجاسة وقد لا يحملها على قدر النجاسة وقدر الماء، وهنا فائدة حديث القلتين التحرز فيما نقص عن القلتين أي في قليل الماء والنظر في أوصافه والاحتياط فيها حتى لا يكون الماء قد تغير دون أن ننتبه، بخلاف الماء الكثير فإنه لا يلزم فيه مثل هذا التحرز لأن الأغلب عليه عدم التأثر والتغير بالنجاسة، وهذا ترجيح شيخ الإسلام ابن تيمية رغم أنه خلاف مذهب الحنابلة المشهور.` },
      { q: `نجاسة الكلب: أحكامها الخاصة (المغلظة)، وهل يقاس عليه غيره في التسبيع؟`, p: `166–167`,
        n: `ومنها: أن الغسل سبعًا ليس عامًّا في جميع النجاسات، وإنما ورد الشرع به في ولوغ الكلب خاصة.`,
        o: `الحنابلة: قاسوا سائر النجاسات على لعاب الكلب فقالوا: يجب غسل كل شيء أصابته نجاسة سبع مرات إحداهن بالتراب.`,
        s: `حديث ولوغ الكلب الذي فيه أن النجاسة لا تغير، فنقول: نجاسة الكلب نجاسة مختصة بعدة أحكام فهي: [نجاسة مغلظة — غير ظاهرة] ومن هنا وجب غسل الإناء الذي ولغ فيه الكلب أو أصابه لعاب الكلب سبعًا سواء ظهر التغير أم لا، لأنها نجاسة خاصة عن النجاسات الأخرى لا يظهر لها لون ولا طعم ولا رائحة وهي مغلظة في نفس الوقت، ومن هنا وجب غسلها في أي الأحوال، فنجاسة الكلب فيها جملة من الخصوصيات، ولذلك لا تحمل عليها سائر النجاسات التي يظهر لونها أو طعمها أو ريحها. الكلام صحيح والاستدلال بالحديث عليه فيه نظر، لأن الحديث أمر بالغسل ثلاثًا لاحتمال النجاسة لا لوجودها ولا لاحتمال نجاسة معنوية بمبيت الشيطان كما ذكرنا فلا يكون فيه دليلًا على ذلك؛ ولكن الأدلة على صحة المسألة أن الغسل لا يلزم سبع مرات في كل النجاسات إحداهن بالتراب هو أن الحديث ورد في الكلب خاصة ولم يرد في غيره وورد في غيره بالغسل مرة حتى يزول أثر النجاسة بل وإذا بقي بعض الأثر اليسير كما في دم الحيض لا يضر، وأمر النبي ﷺ بالاستنجاء بثلاثة أحجار ولم يأمر بغسل الموضع سبعًا وغير ذلك من الأدلة الكثيرة التي تدل على أن المقصود إزالة النجاسة وتطهير الثياب والبدن منها دون الالتزام بسبع، فمفهوم حديث: (إذا ولغ الكلب في إناء أحدكم) أن غيره ليس كذلك خلافًا للحنابلة الذين قاسوا سائر النجاسات على لعاب الكلب فقالوا يجب غسل كل شيء أصابته نجاسة سبع مرات إحداهن بالتراب، ولعل هذا هو سبب شيوع أن المذهب الحنبلي مذهب متشدد وهو بالفعل متشدد في هذا الباب باب الطهارة وهو أن جميع النجاسات حتى البول، فلو أن إنسان أصابه قطرة من البول فلا بد أن يأتي بتراب وهذا مما يجزم أن الشرع لم يأت به وأن النبي ﷺ لم يزل هو وأصحابه تصيبهم أنواع النجاسات في الأبدان والثياب ولم يأمر بذلك ﷺ إلا في الكلب والظاهر من التسبيع أنه أمر تعبدي فكيف يقاس على الأمر التعبدي الغير معقول المعنى فالمعقول المعنى الإزالة، ولذلك نحن التزمنا هذا القول بأن كل ما يزيل النجاسة يصح تطهير الثوب والبدن به، لأن معقول المعنى هو البعد عن النجاسة وإزالتها، والذي يقول أنه تعبدية غير معقولة المعنى فلا يصح القياس على ما هو غير معقول المعنى، ولا نقيس حتى الخنزير، فالخنزير أشد لأنه محرم في ذاته، ولا يلزم من ذلك أنه أشد نجاسة من الكلب، وكما قلنا أنه أمر غير معقول المعنى، وعندما نعلم أن هذا من أجل وجود أنواع من الأذى والضرر المتوقع من لعاب الكلب خلاف غيره من الحيوانات، فهذا أقل ما يمكن به إدراك لماذا خصص الشرع الكلب، إذا كان هناك الأذى والضرر والميكروبات المتعلقة بلعاب الكلب والله ﷻ أعلم، فوارد جدًّا وجود معاني خفية في الكلب لا نعلمها، فطالما أن الأمر ورد تعبدًا بسبع مرات إحداهن بالتراب فعلينا أن نلتزم بما ورد ونلتزم مع باقي النجاسات بمعقول المعنى من أن المقصود من التطهير هو إزالة النجاسة، فإذا أزيلت النجاسة بأي مزيل حصل التطهير. قول الإمام البخاري الذي يقول اللعاب هو المخصص، ولكن لا شك في نجاسة البول لنجاسة بول كل غير مأكول اللحم، فظاهر حديث: (كانت الكلاب تبول وتقبل وتدبر في المسجد في زمان رسول الله ﷺ فلم يكونوا يرشون شيئًا من ذلك) البخاري، دليل على عدم لزوم غسل الأرض التي أصابها بول الكلب سبعًا لأنهم كانوا يبولون في الطريق وكانوا يكتفون بالجفاف في تطهير هذه الأرض والله أعلم. والإمام مالك التزم في لعاب الكلب بطهارته والتزم التعبد في جميع أحكام لعاب الكلب فقال: الغسل تعبدي مع طهارته وكذلك تكرارها سبع تعبدًا، والذي يظهر لنا أن الغسل معقول المعنى فنلتزم به ونلتزم في التعبدي بما لا ندري معناه من التراب بخلاف قوله: (طهور إناء أحدكم أن يغسله) ظاهر جدًّا في نجاسة لعاب الكلب وأن التسبيع والتتريب لعلة لا نعلمها لكونها نجاسة مغلظة.` },
      { q: `هل يطهر موضع الاستنجاء بالأحجار أم يبقى نجسًا معفوًّا عنه؟`, p: `167–168`,
        n: `ومنها: أن موضع الاستنجاء لا يطهر بالأحجار بل يبقى نجسًا معفوًّا عنه في حق الصلاة.`,
        o: `الشافعية: يبقى نجسًا معفوًّا عنه.`,
        s: `هذا الكلام غير ظاهر، فكلامهم مبني على: [وجود حجر عليه نجاسة تلمسها يده فتصيب هذا الموضع أو أن يده سوف تلمس عورته التي فيها بقايا من النجاسة فتتنجس] وهذا كله ليس ظاهرًا ولا دليل عليه، بل الصحيح أن موضع الاستنجاء يطهر بالأحجار؛ فالنبي ﷺ قد سمى الاستنجاء بالأحجار طهارة وقال عن الروث والعظم: إنهما لا يطهران، فدل ذلك على أن الحجر يطهر، فلا يصح أن نقول على ما سماه النبي ﷺ عنه أنه طهارة أن نقول إنه معفو عنه فقط بل هناك نجاسة معفو عنها مثل بول الغلام الرضيع فهو نجس خفف في تطهيره وما يبقى من أثره في الثوب معفو عنه، الدم نجس يعفى عن اليسير منه فليس معناه أنه طاهر ولكن خفف في تطهيره وعن اليسير منه؛ فليس هذا بصحيح في مسألة نجاسة محل الاستنجاء، الصحيح أن محل الاستنجاء يطهر بإزالة عين النجاسة وهم قد ذكروا شروط الاستنجاء بالأحجار أن يحصل الإنقاء فلا بد من إزالة آثار عين النجاسة فلو هناك آثار باقية فلا بد من إزالتها وتجب مسحة رابعة وتستحب خامسة إذا لم يحصل الإنقاء إلا بذلك وإذا لم يحصل الإنقاء بالخامسة وجبت السادسة واستحبت السابعة وهكذا حتى يحصل الإنقاء، ووجود الرائحة في موضع الاستنجاء أمر لا أثر له معفو عنها وليس دليلًا على وجود النجاسة، بل يعفى عن رائحة النجاسة، فالصحيح أن موضع الاستنجاء يطهر بالأحجار.` },
      { q: `غسل النجاسة ثلاثًا، والغسل ثلاثًا في المتوهمة، وعدم تأثير الرش فيها`, p: `168`,
        n: `ومنها: استحباب غسل النجاسة ثلاثًا لأنه إذا أمر به في المتوهمة ففي المحققة أولى. ومنها: استحباب الغسل ثلاثًا في المتوهمة. ومنها: أن النجاسة المتوهمة يستحب فيها الغسل ولا يؤثر فيها الرش؛ فإنه ﷺ قال: «حتى يغسلها» ولم يقل حتى يغسلها أو يرشها.`,
        o: NO_O,
        s: `الصحيح أن الأمر بالثلاث تعبدي أيضًا فلا يلزم غسل النجاسة ثلاثًا كما في دم الحيض فلم يأمرها بالغسل ثلاثًا. وأما المتوهمة: الثلاث هذه مثل السبع في الكلب فكما أن هذه تعبدية فهي تعبدية، فالكلب لأنه نجاسة حسية مغلظة فكان والنجاسة الأخرى معنوية للشيطان في الأنف وفي اليد ربما تغسل ثلاثًا.` },
      { q: `الأخذ بالاحتياط في العبادات والفرق بينه وبين الوسوسة، واستعمال الكنايات فيما يستحيى منه`, p: `168`,
        n: `ومنها: استحباب الأخذ بالاحتياط في العبادات وغيرها ما لم يخرج عن حد الاحتياط إلى حد الوسوسة، وفي الفرق بين الاحتياط والوسوسة كلام طويل أوضحته في باب الآنية من شرح المهذب. ومنها: استحباب استعمال ألفاظ الكنايات فيما يتحاشى من التصريح به؛ فإنه ﷺ قال: «لا يدري أين باتت يده» ولم يقل: فلعل يده وقعت على دبره أو ذكره أو نجاسة أو نحو ذلك، وإن كان هذا معنى قوله ﷺ.`,
        o: NO_O,
        s: `بمعنى أن الشيء الذي اعتبره الشرع وأشار إليه بالاحتياط فهو المشروع، وأما ما يتوهم وما يتخيل وهو مجرد احتمال ولم يأت الشرع باعتباره فهو ليس باحتياط. فإن كلمة نجاسة ليس فيها ما يتحاشى من التصريح به، ولكن بناءً على ما فسر به الحديث أولًا وهو احتمال مرور اليد على النجاسة أدى إلى هذا القول.` },
      { q: `غمس اليد في الإناء قبل غسلها عند القيام من النوم: تحريم أم تنزيه؟ وهل يختص بنوم الليل؟`, p: `169–170`,
        n: `هذه فوائد من الحديث غير الفائدة المقصودة هنا، وهي النهي عن غمس اليد في الإناء قبل غسلها، وهذا مجمع عليه، لكن الجماهير من العلماء المتقدمين والمتأخرين على أنه نهي تنزيه لا تحريم، فلو خالف وغمس لم يفسد الماء ولم يأثم الغامس. وحكى أصحابنا عن الحسن البصري — رحمه الله تعالى — أنه ينجس إن كان قام من نوم الليل، وحكوه أيضًا عن إسحاق بن راهويه ومحمد بن جرير الطبري وهو ضعيف جدًّا؛ فإن الأصل في الماء واليد الطهارة فلا ينجس بالشك، وقواعد الشرع متظاهرة على هذا، ولا يمكن أن يقال الظاهر في اليد النجاسة، وأما الحديث فمحمول على التنزيه. ثم مذهبنا ومذهب المحققين: أن هذا الحكم ليس مخصوصًا بالقيام من النوم، بل المعتبر فيه الشك في نجاسة اليد، فمتى شك في نجاستها كره له غمسها في الإناء قبل غسلها، وسواء قام من نوم الليل أو النهار، أو شك في نجاستها من غير نوم، وهذا مذهب جمهور العلماء. وحكي عن أحمد بن حنبل — رحمه الله تعالى — رواية: أنه إن قام من نوم الليل كره كراهة تحريم، وإن قام من نوم النهار كره كراهة تنزيه، ووافقه عليه داود الظاهري اعتمادًا على لفظ المبيت في الحديث، وهذا مذهب ضعيف جدًّا؛ فإن النبي ﷺ نبه على العلة بقوله ﷺ: «فإنه لا يدري أين باتت يده»، ومعناه: أنه لا يأمن النجاسة على يده، وهذا عام لوجود احتمال النجاسة في نوم الليل والنهار وفي اليقظة، وذكر الليل أولًا لكونه الغالب ولم يقتصر عليه خوفًا من توهم أنه مخصوص به بل ذكر العلة بعده.`,
        o: `الحسن البصري وإسحاق والطبري: ينجس الماء إن قام من نوم الليل. وأحمد في رواية وداود: يحرم في نوم الليل ويكره في نوم النهار.`,
        s: `(«وهذا مجمع عليه»: أي عند القيام من النوم.) ما الذي صرفه إلى التنزيه؟! يطالب به الحنابلة وأهل الحديث وأهل الظاهر القائلون بأن الأمر على الوجوب وإن لم نقل بنجاسة الماء، فنحن نقول بلزوم غسل اليد عند القيام من نوم الليل ثلاثًا قبل غمسها في الإناء ولا يلزم من ذلك نجاسة الماء، فلو غمسها فالماء على طهارته ولكن يأثم لمخالفته نهي النبي ﷺ. وأما مسألة مبيت الشيطان على الخيشوم فلم يجعلوا هنا لها اعتبار على الإطلاق، مع أن هذا الأمر أمر تعبدي، ومذهب الإمام أحمد — مع أنه سماه مذهب ضعيف جدًّا — إلا أنه هو الظاهر فإنه اعتمد على لفظ المبيت في الحديث وهذا ظاهر وحتى لا نلتزم بكل الالتزامات المخالفة للمعاني المعقولة، فالأصل في الأحكام أن تعلل بعلل ظاهرة معقولة المعاني وألا يقال بالأمر التعبدي إلا بعد العجز عن تعليلها بعلل معقولة، ومن هنا نقتصر بالقول بأنه أمر تعبدي على ما ورد به بدلًا من أن نذكر جملة من التلازمات مثل التفرقة بين ورود النجاسة على الماء وورود الماء على النجاسة، ومسألة استحباب غسل النجاسة ثلاثًا فهذا الأمر في الحقيقة تعبدي، فالصحيح أن هذه الأمور غير معقولة المعاني فنقتصر على ما ورد دون أن نعمم القياس على غيرها. وغسل اليد ثلاثًا في أول الوضوء مستحب يجزيه عن الغسل ثلاث عند الاستيقاظ فينوي بذلك امتثال الأمرين معًا أجزأه ولا يحتاج إلى تجديد. قد قلنا أن مبيت الشيطان على يده أنه احتمال فتكون نجاسة معنوية فحصل إزالة لأثر الشيطان منها بغسلها ثلاثًا في أول الوضوء، والراجح أن يغسلها ثلاث مرات فقط في أول الوضوء والمسألة فيها اجتهاد فلا يغسل ثلاثًا ثم يتوضأ بثلاثة أخرى. ولو قام ولم يغسل صحت صلاته ولكنه يأثم. ولفظ: (فإنه لا يدري أين باتت يده) ليس صريحًا في أنها لمست نجاسة فقد تكون نجاسة حسية أو معنوية فهو يحتمل الأمرين وورود الاحتمال على أمرين ليس بممتنع. فالمشروع أن يغسل يده ثلاث مرات حتى ولو لم يتوضأ، فلو أنه على سبيل المثال يريد أن يشرب ولا يوجد كوب فعليه أن يغسل يده ثلاث مرات ويستنشق ثلاث مرات ويتناول بيده الماء، ولو لم يرد الوضوء.` },
      { q: `غمس اليد المتيقن طهارتها، وكيفية الاغتراف من إناء كبير`, p: `170`,
        n: `هذا كله إذا شك في نجاسة اليد، أما إذا تيقن طهارتها وأراد غمسها قبل غسلها: فقد قال جماعة من أصحابنا: حكمه حكم الشك؛ لأن أسباب النجاسة قد تخفى في حق معظم الناس فسد الباب لئلا يتساهل فيه من لا يعرف. والأصح الذي ذهب إليه الجماهير من أصحابنا: أنه لا كراهة فيه؛ بل هو في خيار بين الغمس أولًا والغسل؛ لأن النبي ﷺ ذكر النوم ونبه على العلة وهي الشك، فإذا انتفت العلة انتفت الكراهة، ولو كان النهي عامًّا لقال: إذا أراد أحدكم استعمال الماء فلا يغمس يده حتى يغسلها، وكان أعم وأحسن. قال أصحابنا: وإذا كان الماء في إناء كبير أو صخرة بحيث لا يمكن الصب منه وليس معه إناء صغير يغترف به فطريقه: أن يأخذ الماء بفمه ثم يغسل به كفيه أو يأخذ بطرف ثوبه النظيف أو يستعين بغيره.`,
        o: `جماعة من الشافعية: حكمه حكم الشك سدًّا للباب.`,
        s: `الصحيح الأول وهو أنه حتى لو تيقن من عدم وجود نجاسة حسية ظاهرة فليغسلها ثلاثًا لأمر النبي ﷺ.` },
      { q: `المسح على الخف المغصوب أو المصنوع من الحرير (فتوى)`, p: `170`,
        n: NO_N, o: NO_O,
        s: `لا يجوز ذلك لأنه مأمور بنزعه فورًا فهو غير مأذون له في لبسه.` },
      { q: `ما هي مدة المسح للمسافر سفر معصية؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `ليس له مدة للمسح لأنه مأمور بعدم السفر فيجب عليه أن يعود فورًا وأن يتوب من معصيته، فإذا تاب مسح ثلاثًا.` },
      { q: `هل يجوز المسح على الجورب الذي يصف البشرة؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `الصحيح أنه يجوز والأحوط أن يجتنب ذلك مراعاة للخلاف.` },
      { q: `إذا سال لعاب الكلب على الثياب: هل يجب غسله سبع مرات إحداهن بالتراب؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `نعم فهذا قول جمهور العلماء وليس خاصًّا بالآنية، قالوا أن الإناء مفهوم لقب لا يفهم منه مفهوم مخالفة لأن هذا هو الغالب الذي يأتي فيه اللعاب.` },
      { q: `رجل عمله في البحر في بعض المراكب يبعد عن الشاطئ حوالي سبعين كيلو مترًا بعيدًا عن الإسكندرية: هل يترخص برخص السفر؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `فسبعين كيلو كافية جدًّا في أن يأخذ حكم السفر فيقصر ويجمع الصلاة في تلك الحال، فأكثر من تسعة كيلو من الشاطئ بعيدًا عن المدينة فيجوز له أن يجمع ويقصر.` },
      { q: `هل لو ترك عالم يقتدى به شيئًا من المستحبات لتعليم الناس يكون تركه للمستحب في حقه أولى؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `إذا كان الناس يحتمل عندهم الظن بالوجوب فذلك يكون مشروعًا للتعليم أيضًا.` },
      { q: `إذا لمس الكلب الثياب من غير لعاب فماذا نصنع؟ (عرق الكلب) (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `الجمهور على أن عرق الكلب كلعابه والصحيح مذهب الإمام البخاري وهو أن لعاب الكلب هو الذي ورد فيه النجاسة، فالكلاب كانت تمشي في الطرقات وتبول كما ذكرنا ولو كان الكلب كله نجس عرقه مثل لعابه، لرشوا المسجد أو أراقوا عليه الماء، فلما لم يفعلوا ذلك دل على عدم نجاسة عرق الكلب.` },
      { q: `هل عقيقة الجارية يدعى إليها مثل عقيقة الولد؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `مسألة الدعوة إلى العقيقة لم ترد مثل الدعوة إلى الأضحية، فالعقيقة مثل الأضحية، فإن دعى إليها فهو على ما يشاء ليس مشروعًا فهذا أمر مباح في الجارية وللذكر، وأما المشروع بأن تقسم أثلاثًا ويفعل بها ما يفعل بالأضحية.` },
      { q: `هل على الخضروات زكاة؟ (فتوى)`, p: `171`,
        n: NO_N, o: NO_O,
        s: `الخضروات لا زكاة عليها عند جمهور العلماء وهو الصحيح.` },
    ],
  },
  {
    title: `باب حكم ولوغ الكلب (ص172–183)`,
    items: [
      { q: `نجاسة الكلب والاستدلال عليها بلفظ «طهور»، وتقديم الحقيقة الشرعية على اللغوية`, p: `174–175`,
        n: `ففيه دلالة ظاهرة لمذهب الشافعي ﵁ وغيره ممن يقول بنجاسة الكلب؛ لأن الطهارة تكون عن حدث أو نجس وليس هنا حدث فتعين النجس. فإن قيل: المراد الطهارة اللغوية، فالجواب: أن حمل اللفظ على حقيقته الشرعية مقدم على اللغوية.`,
        o: NO_O,
        s: `فالحدث هو الذي يقع من الإنسان فالإنسان هو الذي يحدث منه ذلك الحدث، وهذا هو الأصل في كل كلمة يرد فيها كلمة: (طهور — تطهير — فليطهره) فهذا يدل على وجود النجاسة، وكذلك الأمر بالغسل نفسه هو تطهير وهو دليل على وجود النجاسة وأيضًا التصريح بالنجاسة دليل أصرح على النجاسة بلفظ: (النجس — الرجس) فإنها ألفاظ متقاربة بمعنى واحد وكل منها يدل دلالة صريحة على النجاسة، فالذي يؤخذ منه نجاسة شيء معين إما الأمر بالغسل أو الأمر بالتطهير أو التصريح بالنجاسة. والطهارة اللغوية: التنظيف؛ وهو كلام ظاهر وهو أن اللفظ إذا كان يستعمل في الشرع بمعنى ويستعمل في اللغة بمعنى وفي العرف بمعنى فالأصل في الألفاظ الشرعية أن تقدم الحقيقة الشرعية على الحقيقة اللغوية وهو من أنواع الاشتراك اللفظي كالحج في اللغة: (القصد)؛ ولو اصطلح الناس على معنى معين في كلمة الحج (الحاج فلان) أي الرجل الكبير؛ ووردت كلمة الحج في الشرع، فإذا وردت كلمة الحج في آية أو حديث فعلى أي شيء تحمل؟ تحمل على الحقيقة الشرعية وهو قصد مكة والمشاعر لأداء النسك على التفصيل الوارد في الشرع، من هنا كان حمل اللفظ على حقيقته الشرعية مقدم على الحقيقة اللغوية؛ أما حمل كلام الناس على ما يريدون فهو أولى من حمله على الحقيقة الشرعية وليس هذا من تقديم العرف على الشرع قطعًا فالشرع رد بعض الأمور والأشياء التي مردها إلى ما يتعارف الناس عليه وما يستعملونه، فهنا تقدم الحقيقة العرفية على الحقيقة اللغوية وعلى الشرعية، لاستعمال الناس لهذا اللفظ كرجل قال: (والله لا آكل لحمًا) فأكل سمكًا فنقدم العرف على اللغة والشرع؛ وأما إذا تكلم أهل اللغة فتقدم الحقيقة اللغوية كقولنا: (مات الرجل) فالرجل يقولون هو فاعل (فهي في موقع الكلمة من الإعراب وليس أنه فعل ذلك) والحقيقة أنه أميت؛ فيستعمل كلًّا في موضعه فالغرض المقصود أن كلام الشرع يحمل على الحقيقة الشرعية فالشرع نقل كثيرًا من الألفاظ بكثرة الاستعمال عن معناها اللغوي الأصلي إلى معاني أخرى مثل الصلاة والصيام والحج والزكاة (هي النماء والطهارة) فانتقل من هذا المعنى إلى معنى آخر محدد وبالتالي فلا يجوز حملها على المعنى اللغوي ولا يقول أنا سأدعوا وهذه صلاتي ولا أصلي الصلوات الخمس فهذا خارج من الملة إذا حمل الصلاة على المعنى اللغوي لأن الذي تكلم بهذا المعنى فلا بد أن يحملها على المعنى الشرعي. وعلى هذا فإن كلمة الطهارة استعملت في الشرع في إزالة الحدث والنجس واستعملت في اللغة في التنظيف فيجب حملها على المعنى الشرعي ما أمكن ما لم يأت دليل على خلاف ذلك. ومن ضمن الفوائد في هذا الموضوع مسألة الرجعة؛ حديث: [مره فليراجعها] في طلاق الحائض، ولأن ابن القيم وابن تيمية يقولون بعدم وقوع طلاق الحائض، فيقولون (فليراجعها) على المعنى اللغوي، والحقيقة أن لفظ الرجعة لفظ شرعي، ولغة الرجوع (رجع الرجل إلى بيته) أيًّا ما كان فهو اسم مرة، ولكن الرجعة لها معنى شرعي مستعمل في الشرع، فيجب أن يحمل اللفظ على المعنى الشرعي مقدمًا على المعنى اللغوي لأن من الذي تكلم (مره فليراجعها) صاحب الشرع المبلغ عن الله ﷻ النبي ﷺ ولذلك نقول يجب حمل كلمة (فليراجعها) على المعنى الشرعي وبالتالي وقع الطلاق وحسبت الطلقة طلقة بخلاف لو قال أنه معنى لغوي نقول الحقيقة الشرعية مقدمة على الحقيقة اللغوية.` },
      { q: `نجاسة ما ولغ فيه الكلب، والأمر بإراقته، والفرق بين الكلب المأذون في اقتنائه وغيره (مذهب مالك)`, p: `176`,
        n: `وفيه أيضًا: نجاسة ما ولغ فيه، وأنه إن كان طعامًا مائعًا حرم أكله؛ لأن إراقته إضاعة له، فلو كان طاهرًا لم يأمرنا بإراقته بل قد نهينا عن إضاعة المال. وهذا مذهبنا ومذهب الجماهير أنه ينجس ما ولغ فيه، ولا فرق بين الكلب المأذون في اقتنائه وغيره، ولا بين كلب البدوي والحضري لعموم اللفظ. وفي مذهب مالك أربعة أقوال: طهارته ونجاسته وطهارة سؤر المأذون في اتخاذه دون غيره، وهذه الثلاثة عن مالك، والرابع عن عبد الملك بن الماجشون المالكي أنه يفرق بين البدوي والحضري.`,
        o: `مالك: أربعة أقوال (الطهارة، النجاسة، طهارة سؤر المأذون في اتخاذه، والتفريق بين البدوي والحضري عن ابن الماجشون).`,
        s: `فالأمر بالإراقة من ضمن أدلة النجاسة لأنه صار ممتنعًا الانتفاع به لنجاسته ولا يوجد سبب آخر لعدم الانتفاع إلا هذا، وحديث السبع مرات دليل على تغليظ نجاسة الكلب، ولأجل ذلك صار حكم هذه النجاسة رغم أنها غير ظاهرة لها حكم آخر مختلف عن بقية النجاسات في مسألة التغير لأنها نجاسة لا يظهر أثرها مع كونها غليظة، ومن هنا وجب إراقة ما في هذا الإناء وغسله سبع مرات ولو لم يظهر لها أثر بخلاف باقي النجاسات والتي القاعدة والأصل فيها أنه لا يتغير الحكم من الطهارة إلى النجاسة إلا إذا غلب على طعمه أو لونه أو ريحه فهذا هو الأصل في الماء الكثير، أما إذا كان في نحو بئر أو بحر أو نهر جاري فهذا لا يتنجس، فمن أجل عدم ظهور أثر نجاسة لعاب الكلب اعتبر هذا استثناءً من قاعدة التغير، والعبرة ليست لكونه إناءً ولكن بكونه نجاسة تختلط به النجاسة، فلو كانت نجاسة ظاهرة لها أثر لأثرت فيه، فإن نجاسة الكلب لو كانت نجاسة غيرها بنفس القدر لأثرت فيه لو كان دمًا أو بولًا لو كان في هذا الإناء لأثر فيه، ولذلك وجب إراقة ما في الإناء وعدم استعماله وتطهيره سبع مرات إحداهن بالتراب. وعدم الفرق بين المأذون وغيره هو الصحيح. والمأذون في اتخاذه هو كلب الزرع والماشية والصيد، والغير مأذون فيه فنجس؛ والصحيح في هذه المسألة أن النبي ﷺ رغم ترخيصه أمر بالغسل في الكلاب عمومًا واللفظ العام حجة لقول الجمهور ولذلك قال مسلم في روايته: (ثم رخص في كلب الصيد وكلب الغنم وقال: «إذا ولغ الكلب في الإناء فاغسلوه سبع مرات وعفروه الثامنة في التراب»)؛ وأما تفريق عبد الملك بن الماجشون أي أن الحضري ينجس والبدوي لا ينجس لشدة الاحتياج إليه؛ والمشهور من مذهب مالك طهارته ومع ذلك يقول بوجوب الغسل سبع مرات إحداهن بالتراب وعنده الغسل تعبدي غير معقول المعنى، يرد عليه أنه ﷺ قال: (طهور) والأمر بالإراقة ويرد عليه أيضًا أنه طالما أمكن تعليل الحكم ببعض أوصافه لزم تعليله، فعلة الأمر بالغسل النجاسة وهو علة معقولة المعنى وكونها غير ظاهرة لا يلزم منه أنه ليس بنجس بل إذا كانت نجاسة غير ظاهرة والشرع فيها بالاحتياط فيها بالأمر بغسلها سبعًا إحداهن بالتراب والعدد سبع هو أمر تعبدي غير معقول المعنى يحتاج لأبحاث ولا يدرك بالتأمل وكذلك التراب فقد يدرك علل ذلك بطرق خفية غير ظاهرة فلا يدركها كل متأمل من الفقهاء أو غيرهم من عامة الناس، فلما كان هذا الأمر تعبدي غير معقول المعنى فيمتنع القياس عليه بخلاف ما إذا أدرك معناه فنقيس غيره عليه وهذا هو الذي قاله الحنابلة فقالوا كل النجاسات وعللوا سبع بالنجاسة وهذا غير مدرك، المدرك الظاهر في معنى النجاسة هو أنه إذا زالت النجاسة زال حكمها حسيًّا تزول كدم الحيض فالغسل حتى تزول عين النجاسة وتزول آثارها القابلة للإزالة وبعد ذلك لا يضر الأثر الغير قابل للإزالة من الصفرة البسيطة، وبالتالي الغسل سبع تعبدي غير معقول المعنى لا يمكن القياس عليه.` },
      { q: `إراقة ما ولغ فيه الكلب: واجبة لعينها أم عند إرادة استعمال الإناء؟ وإراقة سائر المياه النجسة`, p: `177`,
        n: `وفيه: الأمر بإراقته وهذا متفق عليه عندنا، ولكن هل الإراقة واجبة لعينها أم لا تجب إلا إذا أراد استعمال الإناء أراقه؟ فيه خلاف: ذكر أكثر أصحابنا أن الإراقة لا تجب لعينها بل هي مستحبة فإن أراد استعمال الإناء أراقه. وذهب بعض أصحابنا إلى أنها واجبة على الفور ولو لم يرد استعماله، حكاه الماوردي من أصحابنا في كتابه الحاوي ويحتج له بمطلق الأمر وهو يقتضي الوجوب على المختار وهو قول أكثر الفقهاء. ويحتج للأول بالقياس على باقي المياه النجسة فإنه لا تجب إراقتها بلا خلاف. ويمكن أن يجاب عنها بأن المراد في مسألة الولوغ الزجر والتغليظ والمبالغة في التنفير عن الكلاب.`,
        o: `أكثر الشافعية: الإراقة مستحبة لا تجب لعينها.`,
        s: `القول بوجوب الإراقة هو الصحيح الذي لا نشك فيه، وهو أن مطلق الأمر يدل على الوجوب مطلقًا في جميع الأشياء. وأما القياس على باقي المياه النجسة: فيمكن أن يجعلها في إناء للحاجة فالنبي ﷺ كان له إناء يتبول فيه بالليل (فعن حكيمة بنت أميمة بنت رقيقة عن أمها أنها قالت: "كان للنبي ﷺ قدح من عيدان تحت سريره يبول فيه بالليل" (د 24) [قال الألباني]: حسن صحيح انظر صحيح الجامع: 4832، وقال الألباني في الصحيحة: 2516: والتوفيق بأن يحمل حديث الترجمة (لا يُنقع بول في طست في البيت، فإن الملائكة لا تدخل بيتًا فيه بول، ولا يبولن في مغتسل) على أن المراد بانتقاعه طول مكثه فلا يعارض حديث أميمة، لأن ما يجعل في الإناء لا يطول مكثه غالبًا. والله أعلم. أ.هـ)، وكان هذا دليلًا على عدم وجوب إراقة النجاسة مطلقًا. والاحتجاج الآخر وهو أن نجاسة الكلب نجاسة غير ظاهرة الأثر وبالتالي فقد تُنسى أما باقي النجاسات الأخرى فآثارها الظاهرة تذكر الإنسان بها، كأناء متنجس ببول أول ما يرى يعرف بلونه أو رائحته، وكذلك إناء به خمر ولو لم يرق حتى لو كان مع أن هناك أمر بإراقتها وليس ذلك لنجاستها فقط بل لسد ذريعة استعمالها لأنه قد يكون ذريعة لشربها ولذلك أمر بإراقتها ومبالغة في الاجتناب، وبالتالي هناك فروق متعددة بين نجاسة الكلب وغيره من النجاسات فالظاهر وجوب الإراقة.` },
      { q: `عدد الغسلات من ولوغ الكلب (سبع أم ثلاث)، وموضع التراب منها`, p: `177–179`,
        n: `وفيه: وجوب غسل نجاسة ولوغ الكلب سبع مرات، وهذا مذهبنا ومذهب مالك وأحمد والجماهير. وقال أبو حنيفة: يكفي غسله ثلاث مرات. وأما الجمع بين الروايات فقد جاء في رواية «سبع مرات» وفي رواية «سبع مرات أولاهن بالتراب» وفي رواية «أخراهن أو أولاهن» وفي رواية «سبع مرات السابعة بالتراب» وفي رواية «سبع مرات وعفروه الثامنة بالتراب»، وقد روى البيهقي وغيره هذه الروايات كلها، وفيها دليل على أن التقييد بالأولى وبغيرها ليس على الاشتراط بل المراد إحداهن. وأما رواية «وعفروه الثامنة بالتراب» فمذهبنا ومذهب الجماهير أن المراد اغسلوه سبعًا واحدة منهن بالتراب مع الماء، فكأن التراب قائم مقام غسلة فسميت ثامنة لهذا.`,
        o: `أبو حنيفة: يكفي غسله ثلاث مرات.`,
        s: `فرغم القول المشهور عند مالك بالطهارة إلا أنه أوجب الغسل سبع مرات سواء قال بطهارته أو قال بنجاسته أو التفريق، فعلى كل الأقوال المنقولة عن مالك فقد قال بوجوب الغسل، ولكن على القول بالنجاسة يكون معقول المعنى، ومع القول بالطهارة يكون تعبدي فيقول هو طاهر يجب غسله. وأخذ أبو حنيفة ذلك من رواية أبي هريرة عن نفسه وهي موقوفة أنه كان يغسل ما ولغ فيه الكلب ثلاث مرات وقالوا أبو هريرة هو راوي حديث السبع مرات وبالتالي رواية الراوي يفسرها فعله (فعله مقدم على روايته)، والذي عليه جمهور العلماء أن رواية الراوي مقدمة على فعله فربما نسي أو تأول ثم إنه ليس أبو هريرة وحده هو الذي روى الأمر بالغسل سبعًا فعندنا رواية عبد الله بن المغفل فهذا يدل على لزوم غسل ما ولغ فيه الكلب سبع مرات إحداهن بالتراب ومعلوم أن هذا الأمر ليس معللًا بالإناء وإنما معلل بولوغ الكلب فلو كانت العلة في الإناء لكانت كل نجاسة تقع في الإناء يلزم غسلها سبعًا ومعلوم أن الإناء إذا وقع فيه بول يجب غسله حتى يزول أثره لأن البعض قد يفرق بين الثوب والإناء فيقول ليس الثوب كالإناء بل ليس كذلك، فلا يوجد أحد من العلماء يقول بذلك، فالذي يقول بالطهارة يقول بالطهارة في الإناء والثياب ويقول الغسل هنا تعبدي ويلتزم بذلك، وأما بالنسبة لمن يقول بالنجاسة وهو الصحيح، فكل ما وقعت فيه نجاسة الكلب وجب غسلها سبع مرات إحداهن بالتراب وعلى هذا فإذا لعق الكلب بلعابه ثوب إنسان أو يده أو رجله أو أي شيء لزم غسله سبع مرات إحداهن بالتراب. وأما الجمع بين الروايات: وهذا هو الأظهر وأن هذه الروايات على التخيير لأن كلها صحيحة الإسناد، فلما قال أولاهن وقال أخراهن دل ذلك على إجزاء إحداهن وأوسعها رواية (إحداهن بالتراب) وهذا مطلق طالما لم يرد تقييده بنفس القيد في كل مرة فبقاؤه على إطلاقه أولى من أن يقيد بلزوم أولاهن أو أخراهن بل نقول رواية (إحداهن) أوسع الروايات وأن الروايات الأخرى موافقة لها، فلا يلزم القول بمفهومها، مفهوم رواية (أولاهن) فليست الثانية أو الثالثة وهكذا وورد (أخراهن) فلا يعمل بمفهومها لأنه ورد ما يخالف هذا المفهوم فضعف جدًّا مفهوم التقييد بالأولى أو الأخيرة، فلما ضعف مفهوم [أولاهن أو أخراهن] رجحنا عليه عموم وإطلاق (إحداهن بالتراب) فتجزيء أي واحدة ويرجح في الأولوية بين الأولى والأخيرة، ويرجح (أولاهن) كثرة الرواية ويرجح (أخراهن) رواية: (وعفروه الثامنة بالتراب) فالصحيح التخيير. وأما (الثامنة) فهذا هو الصحيح، وإلا لو كانت مرة ثامنة بعد السابعة لكان يلزم تاسعة لأن غسله بالتراب لا بد من إزالة التراب فجريان الشيء لا يسمى غسله بالتراب إلا لو كان التراب جاريًا وكيف يجري إلا مع الماء فيوضع التراب مع الماء ليجري ويتم الغسل بذلك.` },
      { q: `حكم سائر أجزاء الكلب (بوله وروثه ودمه وعرقه وشعره) هل تأخذ حكم الولوغ؟`, p: `179`,
        n: `واعلم أنه لا فرق عندنا بين ولوغ الكلب وغيره من أجزائه، فإذا أصاب بوله أو روثه أو دمه أو عرقه أو شعره أو لعابه أو عضو من أعضائه شيئًا طاهرًا في حال رطوبة أحدهما وجب غسله سبع مرات إحداهن بالتراب.`,
        o: `الشافعية: كل أجزاء الكلب كولوغه. والبخاري: التخصيص باللعاب.`,
        s: `لماذا اشترط حال الرطوبة؟ لأنه في غير حال الرطوبة لا تنتقل النجاسة، وهذا عند الشافعية، وأما طريقة الإمام البخاري التخصيص باللعاب فقال: [باب إذا شرب الكلب في إناء أحدكم فليغسله سبعًا]، ويمكن أن يقال بول الكلب وسائر نجاساته، فإنه لا نزاع في نجاسة بول الكلب وروثه ودمه، والخلاف في العرق، بمعنى أنه لو أن أحدًا لمس شعر الكلب، وللعلم فإن الطب الحديث يقول لأن الكلب لا يعرق ولذلك تجده يلهث، فليس عنده غدد عرقية، فكونه له عرق طبيًّا غير صحيح، فإنه يلهث في الحر لعدم وجود غدد عرقية التي تساعد على عملية البخر، ولذا يضطر أن يلهث ليحصل البخر من خلال التنفس.` },
      { q: `فروع في التطهير من الكلب: تعدد الكلاب والولغات، والغسلة الثامنة بالماء، وقيام الصابون مقام التراب، والتراب النجس، والنجاسة التي لا تزول إلا بعدة غسلات`, p: `179–180`,
        n: `ولو ولغ كلبان أو كلب واحد مرات في إناء ففيه ثلاثة أوجه لأصحابنا: الصحيح أنه يكفيه للجميع سبع مرات، والثاني: يجب لكل ولغة سبع، والثالث: يكفي لولغات الكلب الواحد سبع ويجب لكل كلب سبع. ولو وقعت نجاسة أخرى في الإناء الذي ولغ فيه الكلب كفى عن الجميع سبع. ولا تقوم الغسلة الثامنة بالماء وحده ولا غمس الإناء في ماء كثير ومكثه فيه قدر سبع غسلات مقام التراب على الأصح، وقيل: يقوم. ولا يقوم الصابون والأشنان وما أشبههما مقام التراب على الأصح، ولا فرق بين وجود التراب وعدمه على الأصح. ولا يحصل الغسل بالتراب النجس على الأصح. ولو كانت نجاسة الكلب دمه أو روثه فلم يزل عينه إلا بست غسلات مثلًا فهل يحسب ذلك ست غسلات أم غسلة واحدة؟ أم لا يحسب من السبع أصلًا؟ فيه ثلاثة أوجه أصحها: واحدة.`,
        o: `الأوجه المذكورة عند الشافعية.`,
        s: `في تعدد الكلاب والولغات: الصحيح الأول، لأن كلهم لهم نفس الحكم، فالنجاسة من نوع واحد فيطهرها ما أمر به النبي ﷺ. وفي الثامنة بالماء: فلو أتيت بشيء خشن ودلكت فلا يقوم مقام التراب ينبغي أن يقال [على الصحيح]، والفرق بينهما هو أن (الأصح) مقابلة (مقابل الأصح) تدل على أن الخلاف فيه قوي جدًّا لأن القولين اجتهاديين محتملين، أما (صحيح) وعكسه (ضعيف) فيدل على أن الخلاف سائغ وهذا على اصطلاح الشافعية وعندما يقولوا (الصواب) فيكون ضده (الباطل) ويكون الخلاف غير سائغ. وفي الصابون: أي في مسألة وجود الصابون، فلو لم يجد التراب فهل يتطهر بالصابون أم يظل نجس؟ وهل لو اضطر إلى استعماله يستعمله مع بقاء النجاسة؟ لأن معناه أنه لو تطهر بالصابون وغيرها فلو وجد التراب فقد تطهر فلا يحتاج التراب ولا يلزمه استعماله مرة أخرى، ولكن يمكن نجيز استعماله للضرورة ولكن حكم النجاسة باقي؛ والقول الآخر الذي يقول هناك فرق بين الاثنين فيقول تطهر لعدم وجود التراب واستعملنا غيره بدلًا منه، وظاهر الحديث (وعفروه الثامنة بالتراب) فلا بد من التراب. ولو لم يغسل الشيء بالتراب سيظل نجس ولا يمكن تطهيره حتى لو أنه سيفسد بالتراب كالشيء المائع الذي يراق لأنه لا يمكن تطهيره بالتراب ولا بغيره، فلو ولغ الكلب في سمن مائع فسوف نريقها لأن النبي ﷺ أمر بالإراقة، ولا يمكن تطهيرها لأن هذا الشيء لا بد أن يتطهر بالتراب. ولا فرق بين الكلب الصغير والكبير فالكلب كلب من ساعة ولادته، والأصل أن الكلاب سباع. وفي التراب النجس: بل ينبغي أن يقال (على الصحيح) لأن التراب النجس يُنجس، وقاله (طهور إناء أحدكم) فإنه لا بد وأن يتطهر فكيف يتطهر بنجس؟ فإنه لا يتطهر بنجس. وفي النجاسة التي لا تزول إلا بعدة غسلات: وهذا لإزالة العين، أي أن النجاسة لا تزال موجودة، فالغسلة الأولى لم تتم بها غسلة، فالغسلة المقصود بها إزالة النجاسة، فالنجاسة لا تزال موجودة هناك نقطة دم موجودة ولا يزال روث الكلب موجود، إذًا لا بد من إزالته ثم بعد ذلك تحسب السبع مرات.` },
      { q: `نجاسة الخنزير: هل تأخذ حكم الكلب في التسبيع؟`, p: `180`,
        n: `وأما الخنزير فحكمه حكم الكلب في هذا كله، هذا مذهبنا. وذهب أكثر العلماء إلى أن الخنزير لا يفتقر إلى غسله سبعًا، وهو قول الشافعي وهو قوي في الدليل.`,
        o: `الشافعية: الخنزير كالكلب.`,
        s: `وهذا خلاف الظاهر، فجمهور العلماء على أن الخنزير نجاسته كسائر النجاسات. ينبغي أن يقال [وهذا قول للشافعي]؛ وهذا يدل على شدة إنصاف النووي مع أنه خلاف المذهب المعتمد وهذا هو الصحيح لأن نجاسة الكلب استقلت بكثير من الأحكام لذلك لا يمكن أن نجعلها حجة لعدم التفريق بين القليل والكثير لأنها لا تؤثر، فقد احتجوا بنجاسة الكلب من ضمن الأدلة على عدم التفريق عندهم فقالوا لو اعتبرت التغير لأنه لا بد وأن تغير النجاسة لون المائع أو طعمه أو ريحه، فهذا الكلب لعابه ليس له طعم ولا لون ولا رائحة ونجس غليظ النجاسة، فنقول هذا له أحكام مستقلة لشدة وغلظ نجاسته.` },
      { q: `صفة الغسل بالتراب، ومسح موضع النجاسة بالتراب، وما ولغ فيه الكلب من ماء كثير أو طعام جامد`, p: `181`,
        n: `قال أصحابنا: ومعنى الغسل بالتراب: أن يخلط التراب في الماء حتى يتكدر، ولا فرق بين أن يطرح الماء على التراب أو التراب على الماء أو يأخذ الماء الكدر من موضع فيغسل به. فأما مسح موضع النجاسة بالتراب فلا يجزي، ولا يجب إدخال اليد في الإناء بل يكفي أن يلقيه في الإناء ويحركه. ويستحب أن يكون التراب في غير الغسلة الأخيرة ليأتي عليه ما ينظفه، والأفضل أن يكون في الأولى. ولو ولغ الكلب في ماء كثير بحيث لم ينقص ولوغه عن قلتين لم ينجسه، ولو ولغ في ماء قليل أو طعام فأصاب ذلك الماء أو الطعام ثوبًا أو بدنًا أو إناء آخر وجب غسله سبعًا إحداهن بالتراب. ولو ولغ في إناء فيه طعام جامد ألقي ما أصابه وما حوله وانتفع بالباقي على طهارته السابقة كما في الفأرة تموت في السمن الجامد.`,
        o: NO_O,
        s: `(«فلا يجزي»: أي لا بد أن يوضع على التراب ماء.) ولا يجب إدخال اليد لمسألة الدلك، قد قلنا الغسل هو جريان الماء أو المغسول به وهنا التراب على الشيء المغسول. ويكفي أن يلقيه: هذا في اللعاب أما نجاسته التي لها جرم فلا بد وأن تزال. وفي الماء الكثير: سبق الكلام على الماء القليل والكثير. والطعام الجامد: لأنه في معنى الإراقة.` },
      { q: `اقتناء الكلاب: ما يجوز منه (الزرع والماشية والصيد)، واقتناؤه لحراسة الدور، والجرو ليُعلَّم، وقتل الكلاب وبيعها`, p: `181–183`,
        n: `وأما قوله: (أمر رسول الله ﷺ بقتل الكلاب ثم قال: ما بالهم وبال الكلاب؟ ثم رخص في كلب الصيد وكلب الغنم) وفي الرواية الأخرى (وكلب الزرع) فهذا نهي عن اقتنائها. وقد اتفق أصحابنا وغيرهم على أنه يحرم اقتناء الكلب لغير حاجة مثل أن يقتني كلبًا إعجابًا بصورته أو للمفاخرة به فهذا حرام بلا خلاف. وأما الحاجة التي يجوز الاقتناء لها فقد ورد هذا الحديث بالترخيص لأحد ثلاثة أشياء وهي: [الزرع والماشية والصيد]، وهذا جائز بلا خلاف. واختلف أصحابنا في اقتنائه لحراسة الدور والدروب وفي اقتناء الجرو ليعلم: فمنهم من حرمه لأن الرخصة إنما وردت في الثلاثة المتقدمة، ومنهم من أباحها وهو الأصح لأنه في معناها. واختلفوا أيضًا فيمن اقتنى كلب صيد وهو رجل لا يصيد. وأما الأمر بقتل الكلب فقال أصحابنا: إن كان الكلب عقورًا قتل، وإن لم يكن عقورًا لم يجز قتله سواء كان فيه منفعة من المنافع المذكورة أو لم يكن. قال الإمام أبو المعالي إمام الحرمين: والأمر بقتل الكلاب منسوخ، قال: وقد صح أن رسول الله ﷺ أمر بقتل الكلاب مرة ثم صح أنه نهى عن قتلها، قال: واستقر الشرع عليه على التفصيل الذي ذكرناه. قال: وأمر بقتل الأسود البهيم، وكان هذا في الابتداء وهو الآن منسوخ. هذا كلام إمام الحرمين ولا مزيد على تحقيقه.`,
        o: `بعض الشافعية: يحرم اقتناؤه لحراسة الدور ولتعليم الجرو.`,
        s: `في الجرو: لأنه سوف لا يتعلم الحراسة إلا وهو صغير والجرو ليس كلب زرع ولا ماشية ولا صيد. وفي حراسة الدور: أي من باب القياس على ما ورد ويقولون أن هذه كانت حاجات العرب في ذلك الوقت، ولكن الشافعية عندهم ترجيح بل وكثير من العلماء يرجح جواز اتخاذه لحراسة الدور ونحوها وليعلم كذلك لأنه لن يصير كلب زرع إلا إذا علم من صغره فهذا مما لا يتم به المقصود إلا به؛ أي من باب القياس على ما ورد في النص والأحوط تجنب اقتناء الكلاب إلا لما ورد في النص (كلب زرع أو صيد أو ماشية). وفي من اقتنى كلب صيد وهو لا يصيد: الراجح أنه لا يجوز له اقتنائه لأنه لا يصيد فلا يستعمله فالمعنى مقصود وليس اللفظ، فإنما يتخذ كلب الصيد للصيد، كرجل يتخذ كلب زرع كان يحرس الزروع سابقًا، فيأتي به للمدينة، فليس هذا كلب زرع، فالصحيح أن المعنى مقصود. وفي القتل: لأنه نسخ، بل ظاهر الكلام أنه نهى عن ذلك فقال (ما بالهم وبال الكلاب)، فالكلب العقور هو الكلب الذي يعقر الناس أو يعقر أشياءهم من الدواب أو البط أو الدجاج ونحو ذلك، فهو مؤذي فيدفع دفع الصائل للأذى فيبعد أولًا فإن لم يندفع إلا بالقتل قتل. فلما وجدهم يقتلونهم قال: (ما بالهم وبال الكلاب) فهذا نوع من الإنكار أي لماذا لم ينتهوا عن قتلها. والكلام على أن من ضمن النسخ قتل الأسود البهيم ليس بظاهر لأن هذا خاص والأحاديث الناهية عن قتل الكلاب عامة فيقدم الخاص على العام، فيقال نهى عن قتل الكلاب إلا الكلب الأسود. والأسود البهيم هو الأسود الخالص التام السواد لأنه شيطان فيجب قتله. و(ما بالهم وبال الكلاب) دليل صريح على عدم الأمر بقتل الكلاب، وهناك دليل على قتل الكلاب، إذًا الحديث دليل على النسخ، وقوله (ثم) فهناك تاريخ فهذا تصريح بالنسخ [عن ابن المغفل قال: أمر رسول الله ﷺ بقتل الكلاب ثم قال: «ما بالهم وبال الكلاب»، ثم رخص في كلب الصيد وكلب الغنم] (ثم رخص) دليل على الاقتناء، فيقتني ما فيه منفعة من الثلاث أو ما قام مقامها على الأصح ويترك الأخرى إلا أن يكون كلبًا عقورًا. وعن جابر بن عبد الله: «أن رسول الله ﷺ نهى عن ثمن الكلب والسنور إلا كلب صيد» قال أبو عبد الرحمن: "هذا منكر" (س 4668) [قال الألباني]: صحيح، يجوز شراء الكلب للحاجة المنصوص عليها. وقول النووي (لا مزيد على تحقيقه): بل ما ذكرنا من المزيد معتبر.` },
      { q: `امرأة صلت وظهر قدمها مكشوف (فتوى)`, p: `183`,
        n: NO_N, o: NO_O,
        s: `الراجح أن الصلاة باطلة إذا كانت عالمة بذلك، فيما تستقبل لا بد أن تغطي.` },
      { q: `وقوع الفأرة في السمن: إذا كان مائعًا يراق، فهل العبرة هنا بالتغير أم أن مثلها مثل الكلب؟ (فتوى)`, p: `183`,
        n: NO_N, o: NO_O,
        s: `لا ليست مثل الكلب فهذه نجاسة معتادة، فإذا لم يقع تغير نهائيًّا، كالأواني الكبيرة جدًّا، فتزال وما حولها.` },
      { q: `حكم جلد الكلب والخنزير (فتوى)`, p: `183`,
        n: NO_N, o: NO_O,
        s: `إذا قلنا بكلام الشافعية فجلد الكلب نجس وبالتالي لا تؤثر فيه الدباغ على الراجح، والراجح أن تقول اللعاب هو النجس وباقي النجاسات الأخرى كالروث والدم والبول فنقول أن جلده ليس بنجس، فدباغه يطهره لأن الدباغ مطهر لما تنجس بالموت.` },
      { q: `لفظة «وعفروه الثامنة بالتراب»: ألا تحتمل استعمال التراب بمفرده؟ (فتوى)`, p: `183`,
        n: NO_N, o: NO_O,
        s: `لا فالنبي ﷺ يقول (يغسله سبع مرات أولاهن بالتراب) فكما قال العلماء أنه يخلط الغسلة الثامنة ماء وتراب.` },
      { q: `حديث القلتين: ما الذي جعلنا نقول إنه لا يطبق معه مفهوم المخالفة؟ (فتوى)`, p: `183`,
        n: NO_N, o: NO_O,
        s: `عموم الحديث الآخر (الماء طهور لا ينجسه شيء) وقلنا تطهير النجاسة بقليل الماء، وقلنا أن هذا خرج مخرج الغالب، فقلنا بعدم مفهوم المخالفة لأن الكلام إذا خرج مخرج الغالب لا يكون له مفهوم، والذي جعلنا نقول خرج مخرج الغالب هو إقرار المخالفين لنا أنه إذا غلب النجس على الماء الذي بلغ أكثر من قلتين تنجس، فهذا ليس شرطًا أن يكون في كل الأحوال.` },
    ],
  },
  {
    title: `باب النهي عن البول في الماء الراكد (ص183–186)`,
    items: [
      { q: `ضبط «ثم يغتسل منه» (الرفع والجزم والنصب) وأثره في المعنى`, p: `184`,
        n: `الرواية (يغتسل) مرفوع أي: لا تبل ثم أنت تغتسل منه، وذكر شيخنا أبو عبد الله بن مالك ﵁ أنه يجوز أيضًا جزمه عطفًا على موضع (يبولن)، ونصبه بإضمار (أن) وإعطاء (ثم) حكم (واو) الجمع، فأما الجزم فظاهر، وأما النصب فلا يجوز لأنه يقتضي أن المنهي عنه الجمع بينهما دون إفراد أحدهما، وهذا لم يقله أحد؛ بل البول فيه منهي عنه سواء أراد الاغتسال فيه أو منه أم لا.`,
        o: NO_O,
        s: `فعلى الرفع: فعطف جملة (لا تبل ثم أنت تغتسل منه) على جملة (ثم أنت تغتسل منه) لذلك صار مرفوعًا، وعلى الجزم: (لا يبولن) فعل مجزوم بلا الناهية (ثم يغتسل منه) أي لا يغتسل منه، وعلى النصب: (ثم أن يغتسل منه). وأما النهي عن البول سواء أراد الاغتسال أم لا: لأن ذلك يمنع منافع الماء ويؤدي إلى تقذيره.` },
      { q: `البول في الماء الراكد والجاري، قليلًا كان أو كثيرًا: تحريم أم كراهة؟`, p: `184–185`,
        n: `وأما (الدائم) فهو الراكد. وقوله ﷺ (الذي لا يجري) تفسير للدائم وإيضاح لمعناه، ويحتمل أنه احترز به عن راكد لا يجري بعضه كالبرك ونحوها، وهذا النهي في بعض المياه للتحريم وفي بعضها للكراهة، ويؤخذ ذلك من حكم المسألة: فإن كان الماء كثيرًا جاريًا لم يحرم البول فيه لمفهوم الحديث، ولكن الأولى اجتنابه. وإن كان قليلًا جاريًا فقد قال جماعة من أصحابنا: يكره، والمختار أنه يحرم؛ لأنه يقذره وينجسه على المشهور من مذهب الشافعي وغيره، ويغر غيره فيستعمله مع أنه نجس. وإن كان الماء كثيرًا راكدًا فقال أصحابنا: يكره ولا يحرم، ولو قيل يحرم لم يكن بعيدًا؛ فإن النهي يقتضي التحريم على المختار عند المحققين والأكثرين من أهل الأصول. وفيه من المعنى: أنه يقذره، وربما أدى إلى تنجيسه بالإجماع لتغيره أو إلى تنجيسه عند أبي حنيفة ومن وافقه في أن الغدير الذي يتحرك بتحرك طرفه الآخر ينجس بوقوع نجس فيه. وأما (الراكد) القليل فقد أطلق جماعة من أصحابنا أنه مكروه، والصواب المختار أنه يحرم البول فيه لأنه ينجسه ويتلف ماليته ويغر غيره باستعماله.`,
        o: `جماعة من الشافعية: البول في القليل الجاري أو الراكد مكروه. والشافعية: في الكثير الراكد يكره ولا يحرم.`,
        s: `فقد قال ﷺ: «لا تبل في الماء الدائم الذي لا يجري» فمفهوم المخالفة أن الماء الجاري ليس كذلك، ووردت أحاديث في النهي عنه فيمكن الجمع بينها وبين مفهوم هذا بأن النهي للتنزيه وأن المفهوم هنا يدل على الجواز. وفي القليل الجاري: الأقرب أنه طالما أن الماء ليس دائم (راكد) فلا يحرم كما يدل عليه مفهوم المخالفة للحديث. وقد يرد سؤال هنا على مسألة دورات المياه الحديثة: فكلها بها مياه موجودة تكون نقية ثم يتبول فيها ويتغوط ثم يجريها بعد ذلك، فالظاهر أن هذا له حكم الماء القليل الجاري، فإنه قليل في هذا الوقت ثم يفتح له الطريق بعد ذلك، فالذي يظهر أن الكراهية التي ذكرنا ترجيح المسألة فيها ومع الحاجة إلى ذلك تزول الكراهة لأن المكروه تنزيهًا تزول كراهته مع وجود الحاجة، ولا شك في وجود الحاجة لاتساع المدن المعاصرة وعدم إمكانية الإبعاد. وفي الكثير الراكد: وذلك على أساس التفرقة بين ما بلغ القلتين وغيرهما، وهذا هو الظاهر من الأدلة تحريم التبول في الماء الكثير الراكد لعموم النهي ولم يفرق بين قليل كان أو كثيرًا. (أي حتى لو قلنا بعدم التنجيس.) (أي مع تكرر البول مرة بعد مرة إلى أن يتغير بالنجاسة فيصبح نجسًا.) (القليل والكثير عند أبي حنيفة ليس القلتين وما دونها بل قلته أنه إذا حرك أحد أطراف الماء تحرك طرفه الآخر، ويتنجس عنده بوقوع قليل النجاسة فيه.) والراجح قول مالك أنه إذا تبول في الماء الراكد الكثير ولم يتغير بالنجاسة لم يتنجس ولا عبرة بالقلة والكثرة كما ذكرنا ولكن يؤدي إلى تقذيره وعدم الانتفاع به ولا مانع أن يكون هذا هو المعنى في الماء الكثير الراكد في التحريم، فليس فقط أمر النجاسة، فمنع المنافع يمكن أن يكون سببًا في التحريم فضلًا عما يؤدي إلى التنجيس بعد ذلك بالاتفاق لو تغير. وفي القليل الراكد: (يتلف ماليته) بمنع المنافع وله قيمه إذا كان موضوعًا في إناء أو نحوه فيؤدي إلى فساد هذه القيمة وضياعها وتلفها. والصواب كما ذكر (والصواب المختار أنه يحرم البول فيه).` },
      { q: `التغوط في الماء، والبول في إناء ثم صبه فيه، والبول بقرب الماء أو الموارد (رد على داود الظاهري)`, p: `185–186`,
        n: `وقال أصحابنا وغيرهم من العلماء: والتغوط في الماء كالبول فيه وأقبح، وكذلك إذا بال في إناء ثم صبه في الماء، وكذا إذا بال بقرب النهر بحيث يجري إليه البول، فكله مذموم قبيح منهي عنه على التفصيل المذكور، ولم يخالف في هذا أحد من العلماء إلا ما حكي عن داود بن علي الظاهري أن النهي مختص ببول الإنسان بنفسه، وأن الغائط ليس كالبول، وكذا إذا بال في إناء ثم صبه في الماء أو بال بقرب الماء. وهذا الذي ذهب إليه خلاف إجماع العلماء، وهو أقبح ما نقل عنه في الجمود على الظاهر. وقال العلماء: ويكره البول والتغوط بقرب الماء وإن لم يصل إليه لعموم نهي النبي ﷺ عن البراز في الموارد، ولما فيه من إيذاء المارين بالماء، ولما يخاف من وصوله إلى الماء.`,
        o: `داود الظاهري: النهي مختص ببول الإنسان بنفسه في الماء.`,
        s: `في التغوط: لأنه أشد تنجيسًا وأكثر منعًا للمنافع. ورد على الظاهرية وذلك لشدة إنكارهم للقياس فقالوا: [أن النهي مختص ببول الإنسان بنفسه، وأن الغائط ليس كالبول، وكذا إذا بال في إناء ثم صبه في الماء أو بال بقرب الماء] وهذا من الجمود الشديد، فالذي لا شك فيه أن التغوط كالبول وأقبح، فالعبرة بالمقاصد. وهذا في الحقيقة ليس ظاهر الحديث بل هو عدم فهم لمقاصد الألفاظ. ولكن لأجل عدم القطع بالضرر وعدم القطع بوصوله إلى الماء كُره ولم يحرم.` },
      { q: `الانغماس في الماء القليل لمن لم يستنج، وصرف الفضلات في البحار والمياه، واستعمال مياه الصرف المعالجة في الزراعة`, p: `186–187`,
        n: `وأما انغماس من لم يستنج في الماء ليستنجي فيه: فإن كان قليلًا بحيث ينجس بوقوع النجاسة فيه فهو حرام لما فيه من تلطخه بالنجاسة وتنجيس الماء، وإن كان كثيرًا لا ينجس بوقوع النجاسة فيه، فإن كان جاريًا فلا بأس به، وإن كان راكدًا فليس بحرام ولا تظهر كراهته لأنه ليس في معنى البول ولا يقاربه، ولو اجتنب الإنسان هذا كان أحسن.`,
        o: `الشافعية: قليل النجاسة على فرج من انغمس في الماء القليل ينجسه كله.`,
        s: `هذا على مذهب الشافعية أن قليل النجاسة المتعلقة بفرجه إذا انغمس في الماء القليل (أقل من القلتين) [فهم يفرقون بين ورود النجاسة على الماء وورود الماء على النجاسة] فبمجرد انغماسه فيه ووجود قطرة من البول على فرجه يتنجس الماء وبالتالي اختلط جسمه كله بالنجاسة (تلطخ بالنجاسة)، وهذا الكلام ليس بظاهر. وهذا الكلام ظاهر والأول ليس بظاهر، لأنه لا يتنجس لأن مثل هذه القطرة على فرجه لا تنجس هذا الماء حتى ولو كان قليلًا لأنها لا تغيره والله أعلم ولكنه خلاف المشروع، وهو أن يتناول الماء ولا ينغمس فيه لأجل الاستنجاء لأنه إذا كان لا ينغمس فيه لأجل الاغتسال والذي ليس على بدنه شيء من النجاسة ومع ذلك لأجل عدم تقليل منافع الماء فالأولى أن ينهى عنه في مسألة الاستنجاء، أما كلامه بعد ذلك فصحيح. مسألة صرف الفضلات من البول والغائط في المياه الدائمة (الراكد) كالبحيرات الصغيرة أمر لا يجوز خصوصًا إذا كان المكان مع كثرة الاستعمال يؤدي إلى التنجيس وصرف المجاري في البحار مكروه إلا إن لم يكن هناك حاجة والأولى اجتنابه والحمل على الكراهة لما ذكرنا من صحة الحديث في النهي عن التبول في الماء الجاري، فلو خُير المسلمون بين إلقاء فضلات البول والغائط في الصحراء مثلًا أو في أماكن بعيدة وبين أن يصرفوها في البحار فلا شك أن الأولى أن يصرفوها في الصحاري وليس في المياه حتى ولو كانت مياه البحار الواسعة جدًّا وخصوصًا مع احتمال تنجيس بعض أجزاء هذه البحار بالتدريج مع كثرة الاستعمال تتنجس الأماكن القريبة من هذا وهو أمر مشهود لعدم إدخالها بالداخل فتظهر الرائحة النجسة في هذا المكان. ويمكن استعمال مياه الصرف في الزراعة ولكن بعد معالجتها بإزالة النجاسة والفضلات منها وتنقية المياه مرة بعد مرة حتى تصبح مياه نقية فيها صفات المياه وبهذا تصلح للزراعة لأن الاستحالة مطهرة على الصحيح من أقوال العلماء وفيه خلاف والعبرة بالأوصاف. ولو استعمل على حالة (الماء النجس) كما في بعض الأماكن في سقي الزرع ففيه خلاف بين العلماء الراجح فيه أن الزرع النابت من هذا الماء النجس لا يكون نجسًا لأن هذا الزرع مستحيل على النجاسة وأنه تحول وتغير ولكن هذا الأمر فيه من الأضرار ما قديقال بكراهيته بسببه. ولا ينبغي أن يوضع روث الإنسان وغائطه كسماد للأرض فهذا فيه من الأضرار بالإضافة إلى الخلاف بين العلماء في نجاسة الزرع النابت منه وكذلك استعمال مياه الصرف الصحي كغذاء نيتروجيني للأسماك كالملاحات التي تربى فيها الأسماك وتصرف فيها مياه الصرف فيها خلاف بين العلماء في نجاسة السمك المتغذي والظاهر أنه مثل الجلالة إن كان تظهر فيه رائحة النجاسة ينهى عن أكلها؛ أما الزرع فلا يظهر فيه رائحة النجاسة ولكن الحيوان من الممكن أن يظهر.` },
    ],
  },
];
